3.반복단어(같은의미 단어)
아들: 31, 32, 35, 36
하나님: 32, 35, 37
마리아: 34, 38, 39
천사: 34, 35, 38
엘리사벳: 36, 40
말씀: 37, 38

4.주제 만들기: 예수님이 탄생할 것을 듣다

5.하나님 찾기(관찰)

6.인간 찾기(관찰)
- 가브리엘에게 아이를 잉태할 것을 듣는 마리아

7.하나님 찾기(해석)

8.인간 찾기(해석)
- 마리아는 자기 앞에 천사 가브리엘이 나타난 것도 놀라운데, 
- 네가 아들을 잉태할 것이고,
- 그 아이는 가장 높으신 분의 아들이고,
- 하나님께 다윗의 왕위를 받을 것이라는 말을 듣게 된다.
- 두렵고 놀라움을 금치 못하는 가운데, 마리아는 이성적으로 나는 처녀인데 어떻게 아이를 갖겠느냐 묻는다.
- 이에 가브리엘이 성령이 임하고 하나님의 능력으로 그렇게 될 것이라 말하고,
- 더불어 임신을 못하는 친척 엘리사벳도 하나님의 능력으로 아이를 잉태하였음을 알린다.
- 마리아는 천사의 말이 자기에게 이루어질 것이라 답한다.
- 그리고 일어나 친족 엘리사벳을 문안하러 간다.

- 수태고지를 받은 마리아의 나이는 약 14세 내외일 것으로 추정된다.
- 어린 소녀에게 일어나 일은 두렵고 당황스럽고, 
- 앞으로 일어날 일을 생각하면 정말 무서운 일이었다.

- 그러나 이 어린 소녀는 담대하게 믿음으로 말씀을 받았다.
- 어찌보면 하나님의 천사가 나타난 것이 놀랍고 기쁘고,
- 하나님의 아들이라 불리는 아이가 태어난다고 하니 정말 기뻤을지 모른다.
- 그러나 그 무엇보다 하나님의 영이 마리아에게 강하게 임하여, 
- 성령의 감동을 받은 상태라고 보는는 것이 바른 생각일 것이다.
- 마리아는 성령의 감동을 받고, 기뻐하며, 그 말씀이 이루어질 것을 믿은 것이다.

9.적용(나) 
- 이 놀라운 이야기에 감사할 따름이다.
- 마리아의 담대한 믿음을 본받아야겠다. 

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-05-06', '누가복음', '1장 41~50절', '&nbsp;', '(누가복음 1장)
41. 엘리사벳이 마리아가 문안함을 들으매 아이가 복중에서 뛰노는지라 엘리사벳이 성령의 충만함을 받아
42. 큰 소리로 불러 이르되 여자 중에 네가 복이 있으며 네 태중의 아이도 복이 있도다
43. 내 주의 어머니가 내게 나아오니 이 어찌 된 일인가
44. 보라 네 문안하는 소리가 내 귀에 들릴 때에 아이가 내 복중에서 기쁨으로 뛰놀았도다
45. 주께서 하신 말씀이 반드시 이루어지리라고 믿은 그 여자에게 복이 있도다
46.  마리아가 이르되 내 영혼이 주를 찬양하며
47. 내 마음이 하나님 내 구주를 기뻐하였음은
48. 그의 여종의 비천함을 돌보셨음이라 보라 이제 후로는 만세에 나를 복이 있다 일컬으리로다
49. 능하신 이가 큰 일을 내게 행하셨으니 그 이름이 거룩하시며
50. 긍휼하심이 두려워하는 자에게 대대로 이르는도다

