2025년 5월07일 
누가복음 1장41절~50절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
엘리사벳: 41절(2) 43절 
마리아: 41절 43절 46절 49절
문안/내게 나아오니: 41절 43절
복이 있도다: 42절 45절 48절

4.주제 만들기: 
엘리사벳을 방문하는 마리아

5.하나님 찾기 (관찰)
복을 주시는 하나님.
큰 일을 행하시는 하나님.
긍휼을 베푸시는 하나님.

6.인간 찾기(관찰)
엘리사벳을 방문하는 마리아.
태에 문을 열어주신 하나님을 찬양하며 기뻐하는 여인들.

7.하나님 찾기(해석)

8. 인간 찾기(해석)
이성적으로나 생리학적으로 받아들이기 불가능한 일들을 인정하며 하나님께 영광을 두 여인의 모습을 볼 수 있다. 

엘리사벳은 노년에 특히  마리아는 숫처녀임에도 임신한 사건으로 인류역사상 전무후무한 사건이다. 

이러한 관점에서 생각할 때 마리아와 엘리사벳이 얼마나 성령 충만한 상태인지 짐작할 수 있다. 

엘리사벳은 오실 예수에 대하여 기뻐하고 마리아 역시 자신은 스스로 비천하다 하며 자신을 선택하신 하나님을 찬양함으로 마리아의 겸손함을 볼 수 있다. 

두 사람의 공통점은 기적을 행하신 하나님의 은혜를 표현하는 동시에 모든 것을 행하시는 주체는 하나님이라고 분명히 표현하고 있다. 

현대에 살고 있는 그리스도인들도 누구나 상상하지 못하는 기쁜 일들이 있을 수 있다. 

전능하신 하나님이 원하신다면 분명 그러한 일들이 일어날 것이다. 

그런 경우라도 늘 주님이 주인이신 것을 인식하는 것이 지혜로운 사람임을 깨우친다.

9.적용(나):
기적을 베푸시는 하나님을 더욱 찬양하는 삶을 살아야겠다.

특별히 일본 전도여행을 앞두고 오늘부터 릴레이 금식기도를 시작한다. 

이번 일본전도 여행때 놀라운 기적의 역사와 은혜가 넘치도록 간절히 기도해야겠다.

10. 영적터치 (단어 또는 구절)
46절: 내 영혼이 주를 찬양하며 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-05-07', '누가복음', '1장 51~60절', '마리아의 노래와 세례 요한의 탄생', '누가복음 1장
51   그의 팔로 힘을 보이사 마음의 생각이 교만한 자들을 흩으셨고
52   권세 있는 자를 그 위에서 내리치셨으며 비천한 자를 높이셨고
53   주리는 자를 좋은 것으로 배불리셨으며 부자는 빈 손으로 보내셨도다
54   그 종 이스라엘을 도우사 긍휼히 여기시고 기억하시되
55   우리 조상에게 말씀하신 것과 같이 아브라함과 그 자손에게 영원히 하시리로다 하니라
56   마리아가 석 달쯤 함께 있다가 집으로 돌아가니라
57   엘리사벳이 해산할 기한이 차서 아들을 낳으니
58   이웃과 친족이 주께서 그를 크게 긍휼히 여기심을 듣고 함께 즐거워하더라
59   팔 일이 되매 아이를 할례하러 와서 그 아버지의 이름을 따라 사가랴라 하고자 하더니
60   그 어머니가 대답하여 이르되 아니라 요한이라 할 것이라 하매

