4.주제 만들기: 마리아의 노래와 세례 요한의 탄생

5.하나님 찾기(관찰)

6.인간 찾기(관찰)
- 하나님을 찬양하는 마리아
- 마리아가 엘리사벳의 집에서 석 달 동안 함께 있다가 집으로 돌아감
- 아들을 낳은 엘리사벳
- 아들의 이름을 요한이라 하겠다 말하는 엘리사벳

7.하나님 찾기(해석)

8.인간 찾기(해석)
- 성령의 감동을 받은 마리아가 하나님을 찬양함
- 친족인 엘리사벳과 마리아가 석 달을 함께 있었던 이유를 생각해 보면 다음과 같을 것이다.
- 첫째, 하나님의 놀라운 역사하심을 누리며, 은혜를 나누었을 것
- 둘째, 마리아의 안정을 위해 엘리사벳과 함께 있는 것이 좋았을 것

- 엘리사벳의 아들이 태어나고 이웃과 친족이 하나님의 긍휼히 여기심을 듣고 함께 기뻐함
- 전통대로 8일 만에 아이에게 할례를 행했고,
- 친족들은 이름을 사가랴로 하려고 했으나,
- 엘리사벳이 요한으로 하겠다고 함.
- 천사 가브리엘이 사가랴에게 아들의 이름을 요한으로 하라고 한 것을 사가랴가 엘리사벳에게 전했을 것으로 보임
- 사가랴는 말을 못하는 상태였으므로 어딘가에 써서 엘리사벳에게 알렸을 것으로 생각됨

9.적용(나) 
- 마리아처럼 역사하신 하나님을 찬양하는 삶을 살아야겠다.
- 천사 가브리엘의 말을 잘 간직하고 그대로 행한 엘리사벳처럼 말씀에 순종하는 삶을 살아야한다.

10.영적 터치(단어/구절)

