12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-05-08', '누가복음', '1장 61~70절', '사가랴의 깨달음과 순종', '[눅1:61-70]
61 그들이 이르되 네 친족 중에 이 이름으로 이름한 이가 없다 하고
62 그의 아버지께 몸짓하여 무엇으로 이름을 지으려 하는가 물으니
63 그가 서판을 달라 하여 그 이름을 요한이라 쓰매 다 놀랍게 여기더라
64 이에 그 입이 곧 열리고 혀가 풀리며 말을 하여 하나님을 찬송하니
65 그 근처에 사는 자가 다 두려워하고 이 모든 말이 온 유대 산골에 두루 퍼지매
66 듣는 사람이 다 이 말을 마음에 두며 이르되 이 아이가 장차 어찌 될까 하니 이는 주의 손이 그와 함께 하심이러라
67 그 부친 사가랴가 성령의 충만함을 받아 예언하여 이르되
68 찬송하리로다 주 이스라엘의 하나님이여 그 백성을 돌보사 속량하시며
69 우리를 위하여 구원의 뿔을 그 종 다윗의 집에 일으키셨으니
70 이것은 주께서 예로부터 거룩한 선지자의 입으로 말씀하신 바와 같이

