2. 본문성경 읽기(3번)

3. 반복단어 찾기(형광펜 추천)
- 이름(61,62,63절)

4. 주제만들기: 사가랴의 깨달음과 순종

5. 하나님 찾기 (관찰)
- 사가랴의 회심과 하나님이 하신 일을 깨닫고 순종하자 입을 열어 말하게 하심

6. 인간 찾기 (관찰)
- 엘리사벳이 아이의 이름을 사가랴로 하지 않고 요한으로 하자, 그의 아버지에게 이름을 확인하려는 사람들,
- 사가랴는 말을 하지 못하는 상황에서 자신의 자녀 이름을 요한이라고 하였고, 사람들은 엘리사벳이 같은 이름을 말했기 때문에 놀람. 직후 입이 열려 말을 할 수 있게 됨
- 사가랴는 성령이 충만하여 예언을 함

7. 하나님 찾기 (해석) 
- 하나님의 뜻을 이루실 때 우리가 준비되지 않는다면 우리를 훈련시키신다. 때로는 그것이 고난이나 삶의 불편한 부분으로 찾아올 수 있는데, 그 과정이 우리를 단련케하는 것이고, 하나님의 깊은 뜻을 깨달을 수 있게 해주신다. 하나님의 계획은 완벽하시다.

8. 인간(해석):
- 사가랴는 말을 못하게 되자, 하나님을 깊이 깨닫게 된다. 그분의 뜻과 그분의 계획은 반드시 이루어짐을 느꼈을 것이다. 하나님을 믿지 못한 자신을 회개하며 돌이켰을 것이다. 그리곤 자신의 자녀 이름을 요한으로 정함으로 하나님 앞에 순종했다. 
- 그러자 하나님께선 사가랴의 입을 열어주셨고, 사가랴는 성령이 충만해져 예언을 하게 되었다. 
- 하나님의 능력을 제한하지 말고, 하나님을 의심하지 말고, 하나님의 계획과 뜻이 무엇인지 깨닫기 위한 노력을 하면서 행동으로 순종하면 하나님께선 반드시 그분의 뜻을 이루신다. 

9. 적용(나): 
- 내가 섬길 수 있는 이 사역에 왜라는 의문을 갖지 말고, 그저 하나님의 일을 할 수 있음에 감사하며 나의 역할을 다해야겠다.

10. 영적터치(단어/구절)
- 그가 서판을 달라 하여 그 이름을 요한이라 쓰매 다 놀랍게 여기더라

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-05-09', '누가복음', '1장 71~80절', '&nbsp;', '(누가복음 1장)
71. 우리 원수에게서와 우리를 미워하는 모든 자의 손에서 구원하시는 일이라
72. 우리 조상을 긍휼히 여기시며 그 거룩한 언약을 기억하셨으니
73. 곧 우리 조상 아브라함에게 하신 맹세라
74. 우리가 원수의 손에서 건지심을 받고
75. 종신토록 주의 앞에서 성결과 의로 두려움이 없이 섬기게 하리라 하셨도다
76. 이 아이여 네가 지극히 높으신 이의 선지자라 일컬음을 받고 주 앞에 앞서 가서 그 길을 준비하여
77. 주의 백성에게 그 죄 사함으로 말미암는 구원을 알게 하리니
78. 이는 우리 하나님의 긍휼로 인함이라 이로써 돋는 해가 위로부터 우리에게 임하여
79. 어둠과 죽음의 그늘에 앉은 자에게 비치고 우리 발을 평강의 길로 인도하시리로다 하니라
80. 아이가 자라며 심령이 강하여지며 이스라엘에게 나타나는 날까지 빈 들에 있으니라

