- 구유(12,16절) 

4. 주제만들기: 그리스도 예수

5. 하나님 찾기 (관찰)
- 천사를 통해 다윗의 동네에 구주가 났음을 알려주심
- 강보에 싸여 구유에 누워있는 아기가 표적이라 말하심

6. 인간 찾기 (관찰)
- 천사들의 말을 듣고 확인하러 간 목자들
- 구유에 있는 아기를 발견하고 천사들의 말을 요셉과 마리아에게 전하는 목자들
- 듣는자들은 목자의 말에 놀라지만 마리아는 그 말을 새기어 생각함
- 목자들은 하나님께 영광과 찬송을 올림

7. 하나님 찾기 (해석) 
- 우리를 구원하기 위해 직접 이 땅에 오신 하나님은 누구에게나 동일한 하나님이기 위해 가장 낮은 곳에서 태어나셨다. 그분의 사랑은 우리가 소망을 품을 수 있게 해주셨다.

8. 인간(해석):
- 마리아는 자신들에게 나타난 목자의 말을 새기어 생각했다. 하나님의 은혜로 예수님을 잉태한 마리아는 하나님이 얼마나 위대하신 분인지 알고 있었다. 마리아의 믿음은 더욱 단단해졌을 것이다. 하나님을 경험하더라도 단단한 믿음을 갖긴 어렵다. 마리아는 깊은 묵상을 통해 하나님을 따르고자 했다.

9. 적용(나): 
- 내 인생에 개입해주신 하나님께 영광을 올려드린다. 하나님으로 인해 보잘 것 없는 나의 인생이 소망을 품고 살아갈 수 있다. 감사를 드려야겠다.
- 하나님의 말씀을 더욱 깊이 묵상해야겠다. 

10. 영적터치(단어/구절)
- 마리아는 이 모든 말을 마음에 새기어 생각하니라

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-05-12', '누가복음', '2장 21~30절', '시므온과 그의 소망, 그리스도와의 만남', '누가복음 2장
21   할례할 팔 일이 되매 그 이름을 예수라 하니 곧 잉태하기 전에 천사가 일컬은 바러라
22   모세의 법대로 정결예식의 날이 차매 아기를 데리고 예루살렘에 올라가니
23   이는 주의 율법에 쓴 바 첫 태에 처음 난 남자마다 주의 거룩한 자라 하리라 한 대로 아기를 주께 드리고
24   또 주의 율법에 말씀하신 대로 산비둘기 한 쌍이나 혹은 어린 집비둘기 둘로 제사하려 함이더라
25   예루살렘에 시므온이라 하는 사람이 있으니 이 사람은 의롭고 경건하여 이스라엘의 위로를 기다리는 자라 성령이 그 위에 계시더라
26   그가 주의 그리스도를 보기 전에는 죽지 아니하리라 하는 성령의 지시를 받았더니
27   성령의 감동으로 성전에 들어가매 마침 부모가 율법의 관례대로 행하고자 하여 그 아기 예수를 데리고 오는지라
28   시므온이 아기를 안고 하나님을 찬송하여 이르되
29   주재여 이제는 말씀하신 대로 종을 평안히 놓아 주시는도다
30   내 눈이 주의 구원을 보았사오니

