4.주제 만들기: 시므온과 그의 소망, 그리스도와의 만남

5.하나님 찾기(관찰)

6.인간 찾기(관찰)
- 율법 대로 태어난 지 팔일 만에 할례를 행하고 
- 잉태 전 천사가 일러준 대로 그 이름을 예수라 함
- 율법 대로 정결 예식 기한이 되어 
- 하나님께 제사 드리려고 예루살렘에 올라감
- 의롭고 경건하여 이스라엘의 위로를 기다리는 시므온 
- 성령이 시므온 위에 계심
- 시므온이 성전에서 아기 예수를 안고 하나님을 찬송함   

7.하나님 찾기(해석)

8.인간 찾기(해석)
- 태어난 아기는 하나님의 아들이지만,
- 마리아와 요셉은 인간에게 주어진 율법과 신앙대로 아기 예수께 할례를 행하고, 
- 하나님께 제물을 바치러 예루살렘으로 감
(레위 지파가 아닌 다른 지파의 첫 남자 아이는 제물로서 성전의 섬김에서 속량된다.)

- 성령님의 인도함을 받는 시므온은 아기 예수가 성전에 오는 날,
- 성령의 감동으로 세상을 구원할 그리스도가 성전에 올 것을 알게 됨
- 시므온은 고대하던 그리스도를 직접 보고, 
- 인간이 누릴 수 있는 최고의 감동과 기쁨을 느끼며,
- 저절로 찬송이 나왔을 것

- 의롭고 경건한 시므온에게 성령이 임하셨고,
- 그리스도가 올 것을 미리 알려주셨다.
- 그리고 자신의 이야기를 요셉과 마리아에게 전함으로,
- 이 아기는 하나님의 아들이고, 그리스도임을 다시 확인시켜주는 역할을 수행한다.
- 이것이 시므온의 소망이요, 사명이었을 것이다.

9.적용(나) 
- 시므온의 소망은 그리스도를 보는 것이었다.
- 세상의 그 어떤 좋은 것이 아니라, 그리스도를 보는 것이 소망이었다.

- 나도 시므온처럼 하나님께서 주신 소망을 품고 묵묵히 살다가
- 그 소망을 이루시는 하나님을 보고
- 하나님을 마음껏 찬양하고 싶다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-05-13', '누가복음', '2장 31~40절', '&nbsp;', '(누가복음 2장)
31. 이는 만민 앞에 예비하신 것이요
32. 이방을 비추는 빛이요 주의 백성 이스라엘의 영광이니이다 하니
33. 그의 부모가 그에 대한 말들을 놀랍게 여기더라
34. 시므온이 그들에게 축복하고 그의 어머니 마리아에게 말하여 이르되 보라 이는 이스라엘 중 많은 사람을 패하거나 흥하게 하며 비방을 받는 표적이 되기 위하여 세움을 받았고
35. 또 칼이 네 마음을 찌르듯 하리니 이는 여러 사람의 마음의 생각을 드러내려 함이니라 하더라
36. 또 아셀 지파 바누엘의 딸 안나라 하는 선지자가 있어 나이가 매우 많았더라 그가 결혼한 후 일곱 해 동안 남편과 함께 살다가
37. 과부가 되고 팔십사 세가 되었더라 이 사람이 성전을 떠나지 아니하고 주야로 금식하며 기도함으로 섬기더니
38. 마침 이 때에 나아와서 하나님께 감사하고 예루살렘의 속량을 바라는 모든 사람에게 그에 대하여 말하니라
39. 주의 율법을 따라 모든 일을 마치고 갈릴리로 돌아가 본 동네 나사렛에 이르니라
40. 아기가 자라며 강하여지고 지혜가 충만하며 하나님의 은혜가 그의 위에 있더라

