2025년 5월14일 
누가복음 2장31절~40절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
시므온: 33절 34절
안나/과부: 36절 37절 
예수: 40절(2)
그에 대한/그에 대하여: 33절 38절

4.주제 만들기: 
아기 예수를 기쁨으로 맞이하는 시므온과 선지자 안나. 

5.하나님 찾기 (관찰)
시므온의 말에 놀라는 요셉과 마리아.
축복하는 시므온.
과부 안나.
성전에서 주야로 금식하며 기도하는 안나.
아기 예수를 맞이하는 선지자 안나.
하나님께 감사드리는 안나.

6.인간 찾기(관찰)
이방을 비추는 빛이신 예수.
영광되시는 예수.
성장함에 강해지고 지혜가  충만하며 하나님의 은혜가 넘치는 예수.

7. 하나님찾기(해석)

8. 인간 찾기(해석)
경건하고 의로운 사람 시므온은 성령의 지시를 받고 아기 예수를 만나 축복기도를 올렸다. 

그는 “이방을 비추는 빛이요” 외친 것을 보면 예수는 이미 모든 인류의 구원자이심을 알 수 있다. 

또한 예수를 통하여 많은 사람이 흥하거나 패할 수 있다고 선포했다. 

천국 복음의 씨를 뿌려도 받는 사람이 있고 외면하여 멸망의 길로 가는 갈림의 길로 간다는 것이다. 

이 부분을 생각할 때 내가 노방전도를 할 때 복음을 받아들이는 준비된 영혼이 있다는 사실을 깨우친다. 사실 모든 백성이 구원을 얻는 것이 주님의 마음일 텐데 안타까운 마음이 든다. 

그래서 아마도 시므온은 예수님을 향하여 믿지 않은 사람들이 ’비방을 받는 표적''이라 말씀하고 있다.

한편 선지자 안나는 결혼 후 7년 후 과부가 된 슬픈 여인이었지만 영적인 사람이었음을 알 수 있다. 

84세의 노년이어도 성전에서 성실하게 주야로 금식 기도를 생활하는 것 보면 신실한 하나님 종 임을 알 수 있다. 그러한 안나는 아기 예수를 접대하고 하나님께 감사를 올렸다. 

하나님의 비전을 알고 찬양하는 사람들의 특징은 늘 기도의 사람들인 것을 볼 수 있다. 안나는 나이도 많고 인생도 굴곡이 있었지만, 누구보다도 행복한 삶을 살았던 사람임이 확실하다. 

어떠한 환경에서도 겸손하게 주님께 기도로 나아가고 하나님을 찬양하는 사람들은 늘 하나님이 은혜를 부어주시는 것 같다.

9.적용(나):
어떠한 환경에서도 늘 주님을 의지하고 찬양하는 삶을 살아내야겠다.

10. 영적터치 (단어 또는 구절)
32절:이방을 비추는 빛이요

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

