43   그 날들을 마치고 돌아갈 때에 아이 예수는 예루살렘에 머무셨더라 그 부모는 이를 알지 못하고
44   동행 중에 있는 줄로 생각하고 하룻길을 간 후 친족과 아는 자 중에서 찾되
45   만나지 못하매 찾으면서 예루살렘에 돌아갔더니
46   사흘 후에 성전에서 만난즉 그가 선생들 중에 앉으사 그들에게 듣기도 하시며 묻기도 하시니
