48   그의 부모가 보고 놀라며 그의 어머니는 이르되 아이야 어찌하여 우리에게 이렇게 하였느냐 보라 네 아버지와 내가 근심하여 너를 찾았노라
49   예수께서 이르시되 어찌하여 나를 찾으셨나이까 내가 내 아버지 집에 있어야 될 줄을 알지 못하셨나이까 하시니
50   그 부모가 그가 하신 말씀을 깨닫지 못하더라
