아버지: 48, 49
어머니: 48, 51

4.주제 만들기: 소년 예수

5.하나님 찾기(관찰)
- 예루살렘에 간 예수님
- 요셉과 마리아와 함께 내려가지 않고 성전에 남아있는 예수님 

6.인간 찾기(관찰)
- 해마다 유월절을 지키기 위해 예루살렘에 간 요셉과 마리아
- 예수님이 열 두 살이 되자 요셉과 마리아는 예수님을 데리고 성전에 감
- 절기를 지키고 집에 돌아가는데 예수님을 놓고 감
- 하룻길을 가고 나서야 예수님이 없는 것을 깨닫고,
- 사흘을 뒤에 성전에서 만남
- 예수님과 토론하는 랍비들

7.하나님 찾기(해석)
- 소년 시절 예수님은 예루살렘 성전에 가는 것이 정말 기뻤을 것이다.
- 요셉과 마리아가 집으로 돌아가지만,
- 예수님은 하나님의 집, 성전에 있는 남아 있는 것을 택한다.
- 그것이 이 땅에 내려온 소명이기 때문이다

- 그러나 예수님은 요셉과 마리아의 말에 순종하여, 
- 집으로 돌아가서 요셉과 마리아를 받들었다.

- 한편, 요셉과 마리아가 아무리 정신이 없어도 아들을 놓고 온다는 것은 말이 안되는데,
- 평소 예수님이 얼마나 부모님의 말씀을 잘 들었는지 엿볼 수 있는 부분이다.

- 소년 예수님은 육체적, 정신적, 영적으로 잘 성장하고 있었다. 

8.인간 찾기(해석)
- 유월절 절기를 성실히 지키는 모습을 볼 때 요셉과 마리아는 믿음이 견고한 사람들이었다.
- 나사렛에서 예루살렘까지의 거리는 약 130km이다. 
- 당시 성전은 절기를 지키러 온 사람들로 인해 상당히 복잡했을 것이다.
- 평소 똑똑하고 순종하던 아들이 잘 따라오리라 생각했지만, 곁에 없는 것을 알고는 정말 놀랐을 것이다.
- 이는 하나님의 아들이기에 더욱 놀랐을 것이다. 그런데 곁에 없는 것을 안 시점은 하룻길이나 오고 나서였다.
- 12살 아들이 하루 동안 걸어온 길 중 어디에 있을지, 과연 지금 안전한 것인지 알 수가 없었기에 그들은 정말 당황스럽고 걱정이 많이 됐을 것이다.
- 무려 사흘 뒤에 예수님을 찾았는데, 그냥 걸어가면 하루 걸리는 거리를 사흘 만에 도착했다는 것은 여기저기 수소문 하며 성전까지 갔다는 것이다.
- 아들을 잃은 부모의 마음이 정말 괴로웠을 것이다. 아마도 펑펑 울면서 찾지 않았을까..

- 랍비들은 소년과 토론하며 그의 지혜와 대답에 놀라움을 금치 못했다.
- 아마도 예수님의 질문과 대답이 랍비들을 압도한 것으로 유추된다.
- 당시 랍비들은 최고의 엘리트였다.

- 아들을 찾은 마리아와 요셉은 안도의 한숨을 길게 내쉬었고,
- 마리아는 아들아 아빠와 내가 애타게 너를 찾았다고 말했다.
- 그리고 내가 아버지의 집에 있어야 할 줄 알지 못하셨나이까 라는 예수님의 대답을 마음에 두었다.

9.적용(나) 
- 육체적, 정신적, 영적으로 균형 있게 성장하신 예수님, 
- 그리고 부모에게 순종한 예수님을 따라,
- 나도 영육혼의 균형을 잘 맞추고, 자녀들 또한 그렇게 될 수 있도록 잘 양육해야겠다.

