6. 인간 찾기 (관찰)
- 하나님의 말씀이 요한에게 임함
- 요한은 요한 강 부근 각처에서 죄사함을 받게하는 회개의 세례를 전파함

7. 하나님 찾기 (해석) 
- 하나님은 요한을 통해 예수님이 오실 것을 예언하게 하셨다. 이는 선지자 이사야의 예언을 성취하기 위함이기도 하다.
- 하나님의 계획이 얼마나 치밀한지, 완벽한지 깨닫는다. 이리도 완벽한 하나님을 어찌 믿지 않을 수 있을까? 
- 우리를 향한 하나님의 계획도 완벽하다.

8. 인간(해석):
- 사람들에게 권면하는 행동은 쉬운 일이 아니다. 요한은 자신에게 주어진 하나님의 말씀으로 인해 담대히 말씀을 전할 수 있었다. 
- 당시 유대인에게 영향력과 권위가 있으려면 요한이 얼마나 바르게 살았는지 생각해 본다. 이 시대를 살아가는 우리는 크리스천이지만 교회를 다니지 않는 사람들에게 얼마나 영향력을 미치는지 모르겠다.

9. 적용(나): 
- 나의 연약한 골짜기를 메우고, 교만한 산이 낮아지며, 의로운 길, 바른 길, 평탄한 길을 만들어서 예수님을 믿지 않는 사람들에게 선한 영향력과 말씀의 권위를 끼치는 삶을 살아야겠다. 

10. 영적터치(단어/구절)
