7. 하나님찾기(해석)

예수님의 겸손하심을 깨우치게 된다. 

피조물인 인간 침례 요한에게 기독교에서 거룩한 의식 중 하나인 침례를 성자 하나님이신 예수님께서 자원하여 받으셨다. 

그때 하늘의 문이 열리고 전능하신 하나님께서 기뻐하시며 "너는 내 사랑하는 아들이라" 말씀하신다. 성령님이 비둘기 같이 오셨다고 기록된 것 보니 그 순간 성부 성자 성령 님의 삼위일체를 볼 수 있다. 

그럴 뿐만 아니라 예수님의 족보를 의도적으로 기록한 것으로 보면 겸손하심과 더불어 인간과 깊은 연합의 성취를 표현하고 있는 것 같다.


8. 인간 찾기(해석)

