침례를 베풀거니와: 16절(2)
나보다 능력이 많으신 이/그는: 16절
침례요한: 16절(2) 19절

4.주제 만들기: 
예수님을 높이는 침례요한

5.하나님 찾기 (관찰)
성령의 불로 침례를 베푸시는 예수.

6.인간 찾기(관찰)
세리들과 군인들에게 가르치는 침례요한.
침례요한이 그리스도 인지 묻는 사람들.
예수님을 높이는 침례요한.
분봉 왕 헤롯의 잘못된 행동을 비판하는 침례요한.
이 일로 감옥에 갖힌 침례요한.

7. 하나님찾기(해석)

8. 인간 찾기(해석)
침례 요한은 의롭고 경건하며 겸손한 사람이다. 

다가와서 행할 바를 묻는 세리들 이나 군인들한테 하나님 자녀로서 바르게 사는 법을 가르쳤다. 

그리고 절대 권위자인 분봉 왕 헤롯의 비도덕적인 행실을 지적하였다. 이 일로 그는 비록 감옥에 갇혔지만, 악과 적당히 타협하지 않는 빛 같은 존재였다. 

그러면 침례 요한이 이러한 바르고 정의로운 행동을 할 수 있는 힘의 원동력은 어디에서 온 것일까?

내 생각은 아마도 그의 주를 향한 겸손함이라 여겨진다. 침례 요한에게 침례를 받기 위하여 다양한 사람들이 몰려왔다. 

그리고 침례 요한에게 묻는다. 당신이 혹시 우리가 기다리는 그리스도 인가요? 그 질문에 침례 요한은 조금도 망설이지 않고 대답한다. 

"나는 그의 신발 끈을 풀기도 감당하지 못하겠노라." 외치면서 절대 겸손한 태도를 보여준다.

 누구나 자신을 낮추고 주님을 높이는 사람은 주님의 영이 그와 함께 하사 바른길로 갈 수 있는 용기와 능력을 주심을 깨우친다.

9.적용(나):
세상의 인기보다 오직 주님안에서 겸손하며 주님을 높이는 사람이 되도록 더욱 노력해야겠다.

10. 영적터치 (단어 또는 구절)
