4.주제 만들기: 
성령의 능력으로 사역하시는 예수.

5.하나님 찾기 (관찰)
마귀의 시험을 물리치신 예수.
회당에서 성경을 읽으시는 예수.

6.인간 찾기(관찰)
예수님을 주목하는  회당장 사람들.

7.하나님 찾기(해석)
예수님은 성령의 능력으로 마귀와의 시험을 이기셨다. 

또한 성령의 충만함으로 이사야서의 기록된 하나님 말씀을 선포하셨다.

주님도 사역하실 때 이토록 성령의 능력으로 행하시는데 피조물인 인간은 더욱 성령님을 의지해야 함을 알게 된다. 

한편 예수님께 패배했던 마귀가 쫓겨날 때 잠시 떠나있다고 기록된 것을 보면 하물며 하나님 자녀라도 언제든 기회가 되면 공격할 수 있음을 알게 된다. 

승리하는 삶을 살기 위해서는 늘 깨어 기도하고 말씀을 묵상함으로 성령의 충만함을 갖는 것만이 마귀를 대적하는 유일한 방법이라 여겨진다.

8. 인간 찾기(해석)
회당에서 하나님의 능력의 말씀을 듣고 주목하는 사람들. 

늘 익숙하게 들었던 문자적 말씀이 아닌 성령의 능력의 주님의 말씀을 직접 들었던 사람들의 심정은 어떠한 심정이었을까? 

개인적으로 많이 부럽다. 살아계신 주님의 설교를 직접듣는 것은 축복중의 축복임이 확실하다.

9.적용(나):
하나니의 말씀을 선포할때  늘 성령의 능력으로 전파 하도록 더욱 기도로 준비해야겠다.

