4.주제 만들기: 고향에서 배척받으시는 예수님

5.하나님 찾기(관찰)
- 예수님이 나사렛 회당에서 이사야 말씀을 인용하여 선포하신 후에
- 이 글이 오늘 너희 귀에 응하였다 말씀하심
- 고향 사람들에게 배척을 당하심

6.인간 찾기(관찰)
- 예수님의 말씀을 듣고 감동했으나,
- 곧 말씀을 받아들이지 못하고, 요셉의 아들이 아니냐 말함
- 예수님을 배척함

7.하나님 찾기(해석)
- 나사렛 선언이라 불리는 눅4:18~19을 선포하신 후 이 글이 오늘 너희 귀에 응하였다 말씀하셨는데, 이 것은 그 말씀의 실제가 자신임을 보이신 것이다.
- 회당에 우뚝 서서 이 말이 너희 귀에 응하였다 말씀하시는 예수님의 태도와 모습은 은혜로웠다.

- 가버나움에서 행하신 기적을 볼기를 원하는 고향 사람들에게 기적을 베풀지 않으시고,
- 엘리야와 엘리사 시대의 사례를 말씀하시며 이방인에게 기적이 일어난 것을 말씀하심
- 이것은 주의 은혜의 해가 이스라엘이 아니라 이방 사람들에게 갈 것이라는 말씀으로 고향 사람들이 화가 나게된 이유가 되었다.

- 예수님을 낭떠러지로 떠미는 군중들 가운데로 지나가심으로 그들이 바라던 기적을 보이셨다.
- 예수님은 고향 사람들을 신적 능력으로 통과하여, 가난한 자들에게 은혜의 해를 선포하러 가신 것이다. 

8.인간 찾기(해석)
- 이 말씀이 이루어졌다 말씀하시는 예수님을 바라보며, 아름다움을 느끼며 감동을 받았으나,
- 이내 요셉의 아들 예수 아니냐 말하며 믿지 못하겠다 말함.
- 엘리야와 엘리사 시대를 예로 든 예수님의 말씀을 듣고,
- 구원이 이방인에게 간다는 그 말씀에 화가 나서 예수님을 죽이려고 낭떠러지로 끌고가 밀쳐 떨어뜨리려고 함.
- 그들은 예수님이 메시아라면 이방인이 아니라 이스라엘을 구원해야 하고, 그 방법은 강력한 힘으로 로마를 굴복시키는 것이라 여겼음.

9.적용(나) 
- 예수님이 오심으로 주의 은혜의 해는 임하였다.
- 나는 이천 년 전에 성취된 이 은혜의 날들을 누리며, 
- 예수님을 따라 복음을 전하는 삶을 살아야겠다.
- 이제 내일(5.23.)이면 일본으로 전도여행을 간다.
- 빛으로 오신 예수님께서 일본 땅을 밝게 비추시고,
- 준비된 한 영혼을 우리 앞으로 보내주시길 간절히 원한다.

10.영적 터치(단어/구절)
  21   이에 예수께서 그들에게 말씀하시되 이 글이 오늘 너희 귀에 응하였느니라 하시니

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-05-22', '누가복음', '4장 31~44절', '귀신들린자들과 병자들을 고치시는', '[눅4:31-44]
31 갈릴리의 가버나움 동네에 내려오사 안식일에 가르치시매
32 그들이 그 가르치심에 놀라니 이는 그 말씀이 권위가 있음이러라
33 회당에 더러운 귀신 들린 사람이 있어 크게 소리 질러 이르되
34 아 나사렛 예수여 우리가 당신과 무슨 상관이 있나이까 우리를 멸하러 왔나이까 나는 당신이 누구인 줄 아노니 하나님의 거룩한 자니이다
35 예수께서 꾸짖어 이르시되 잠잠하고 그 사람에게서 나오라 하시니 귀신이 그 사람을 무리 중에 넘어뜨리고 나오되 그 사람은 상하지 아니한지라
36 다 놀라 서로 말하여 이르되 이 어떠한 말씀인고 권위와 능력으로 더러운 귀신을 명하매 나가는도다 하더라
37 이에 예수의 소문이 그 근처 사방에 퍼지니라
38 예수께서 일어나 회당에서 나가사 시몬의 집에 들어가시니 시몬의 장모가 중한 열병을 앓고 있는지라 사람들이 그를 위하여 예수께 구하니
39 예수께서 가까이 서서 열병을 꾸짖으신대 병이 떠나고 여자가 곧 일어나 그들에게 수종드니라
40 해 질 무렵에 사람들이 온갖 병자들을 데리고 나아오매 예수께서 일일이 그 위에 손을 얹으사 고치시니
41 여러 사람에게서 귀신들이 나가며 소리 질러 이르되 당신은 하나님의 아들이니이다 예수께서 꾸짖으사 그들이 말함을 허락하지 아니하시니 이는 자기를 그리스도인 줄 앎이러라
42 날이 밝으매 예수께서 나오사 한적한 곳에 가시니 무리가 찾다가 만나서 자기들에게서 떠나시지 못하게 만류하려 하매
43 예수께서 이르시되 내가 다른 동네들에서도 하나님의 나라 복음을 전하여야 하리니 나는 이 일을 위해 보내심을 받았노라 하시고
44 갈릴리 여러 회당에서 전도하시더라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

1. 1분기도

2. 본문성경 읽기(3번)

3. 반복단어 찾기(형광펜 추천)
-가르치다(31,32절)
-귀신(33,35,36,41절)
-권위(32,36절)
-꾸짖다(35,39절)

4. 주제만들기: 귀신들린자들과 병자들을 고치시는
예수님

5. 하나님 찾기 (관찰)
- 귀신을 꾸짖으시고 내쫓으심
- 소문이 사방에 퍼지자 회당에서 나가심
- 시몬의 장모를 고치시고 찾아오는 병자들을 고치심
- 날이 밝자 한적한 곳으로 나오신 예수님
- 다른 곳에서도 복음을 전하기 위해 보내심을 받았다고 하시며 갈릴리 여러 회당에서 복음을 전하심
6. 인간 찾기 (관찰)
-예수님이 귀신을 쫓는 모습에 권위와 능력을 보는 사람들
-시므온의 장모를 고치신 것을 알자 병자들을 데려오는 사람들
-예수님이 떠나지 못하게 만류하는 사람들

7. 하나님 찾기 (해석) 
- 말씀에는 권위와 능력이 있다. 인간으로 오신 예수님은 말씀으로 능력을 보이셨다. 
- 예수님을 귀신을 쫓으시고, 병자를 고치심으로 연약한 자들을 돌보셨다. 그 후 사람들이 예수님을 찾을 때 예수님을 다른 곳으로 이동하시는데 복음을 전하는 사명과 스스로를 통제하는 겸손의 모습을 볼 수 있다. 
- 예수님을 통해 인기는 유익하지 않음을 깨닫는다. 예수님을 따르고자 했던 사람들이 예수님을 십자가에 매달았다. 

8. 인간(해석):
- 예수님의 능력에 많은 사람들이 놀랐을  것이다. 이러한 소문은 금새 퍼졌을 것이고 예수님이 이스라엘을 다시 일으켜 세울 구원자라 생각했을 것 같다
- 그렇기 때문에 그들은 예수님을 붙잡고자 했다. 세상을 구원하실 예수님의 생각과 자신만 구원받으면 되는 사람들의 입장 차이를 볼 수 있다. 
- 아마 내 삶도 나와 내 가정만 구원 받으면 된다는 생각이 클 것이다. 그러나 예수님의 사랑은 다르다.  예수님을 우리 모두를 사랑하신다. 

9. 적용(나): 
- 우리 가족(한국)만이 아니라 전세계에 하나님 나라 복음을 위해 더욱 전도에 힘써야겠다

10. 영적터치(단어/구절)
- 43 예수께서 이르시되 내가 다른 동네들에서도 하나님의 나라 복음을 전하여야 하리니 나는 이 일을 위해 보내심을 받았노라 하시고
11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-05-23', '누가복음', '5장 1~10절', '', '(누가복음 5장)
1.  무리가 몰려와서 하나님의 말씀을 들을새 예수는 게네사렛 호숫가에 서서
2. 호숫가에 배 두 척이 있는 것을 보시니 어부들은 배에서 나와서 그물을 씻는지라
3. 예수께서 한 배에 오르시니 그 배는 시몬의 배라 육지에서 조금 떼기를 청하시고 앉으사 배에서 무리를 가르치시더니
4. 말씀을 마치시고 시몬에게 이르시되 깊은 데로 가서 그물을 내려 고기를 잡으라
5. 시몬이 대답하여 이르되 선생님 우리들이 밤이 새도록 수고하였으되 잡은 것이 없지마는 말씀에 의지하여 내가 그물을 내리리이다 하고
6. 그렇게 하니 고기를 잡은 것이 심히 많아 그물이 찢어지는지라
7. 이에 다른 배에 있는 동무들에게 손짓하여 와서 도와 달라 하니 그들이 와서 두 배에 채우매 잠기게 되었더라
8. 시몬 베드로가 이를 보고 예수의 무릎 아래에 엎드려 이르되 주여 나를 떠나소서 나는 죄인이로소이다 하니
9. 이는 자기 및 자기와 함께 있는 모든 사람이 고기 잡힌 것으로 말미암아 놀라고
10. 세베대의 아들로서 시몬의 동업자인 야고보와 요한도 놀랐음이라 예수께서 시몬에게 이르시되 무서워하지 말라 이제 후로는 네가 사람을 취하리라 하시니

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2025년 5월24일 
누가복음 5장1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
어부 시몬 베드로:: 4절 5절 8절 10절
그물 내림: 2절 4절 5절 6절 
물고기: 4절 6절 9절
잡다/잡지 못하다: 4절 5절
예수: 1절 3절 8절 10절

4.주제 만들기: 
어부 베드로를 부르시는 예수.

5.하나님 찾기 (관찰)
무리에게 말씀을 가르치시는 예수.
베드로에 그물을 깊은 곳에 던지라고 말씀하시는 예수.
베드로를 복음의 일꾼으로 부르시는 예수.

6.인간 찾기(관찰)
예수님의 말씀을 듣는 사람들.
밤새도록 물고기를 잡지 못한 베드로.
예수님의 말씀을 의지하여 깊은 곳에 그물을 던짐으로 많은 물고기를 잡은 베드로.
그때 자신이 죄인이라 고백하는 베드로.

7.하나님 찾기(해석)
예수님은 함께 사역에 제자를 선택하실대 외형적인 화려함이나 뛰어남을 보지 않으시고 성실한 태도를 보신 듯하다. 

그러한 베드로를 선택하사 이제는 고기 잡는 어부에서 사람을 취하는 복음의 사람으로 인도하신다.

8. 인간 찾기(해석)
베드로는 평생 어부로 살아온 사람이었다. 

그날은 밤새도록 그물을 내렸지만 한 마리도 잡지 못했다. 

그 모습을 보고 계신 예수님께서 깊은 곳에 그물을 내리라고 말씀하셨다. 

예수님을 처음 본 베드로는 그대로 예수님의 말씀에 순종하여 배가 잠길 정도로 물고기를 잡았다. 

그때 베드로는 예수님이 특별한 분이신 것을 느끼고 고백했다. "주여 나를 떠나소서 나는 죄인이로소이다" 라고 말했다. 

이 부분에서 궁금한 점이 있다. 베테랑 어부 베드로는 왜 굽히고 처음 본사람의 말을 들었을까? 

두 번째는 은혜를 경험하고 곧바로 자신을 죄인이라 고백하였을까? 

성경에는 구체적으로 기록하지 않았지만 주님의 압도적인 권능을 베드로는 느끼고 있었을 것이라 추측할 수 있다. 

또 하나는 베드로의 뚝심과 단순성의 성품도 순종함에 작용을 하였을 것이다. 

종일 밤이 새도록 그물을 던진 모습과 곧바로 말씀에 따르는 모습을 보니 상상이 된다

9.적용(나):
 일본선교와서 오늘 자살률이 높은 지하철역에서 전도를 하였다. 

그동안 팀원들과 금식하며 준비해왔는데 많은 은혜가 있었다. 

기독교인들을 심하게 배척하는 일본인들 이었지만 그곳이 깊은 곳이라는 말씀을 의지하여 팀원들과 복음의 그물을 내렀다. 

모든 것이 하나님 은혜이다. 앞으로도 주님 말씀을 더욱 의지하여  복음 전파하는데 앞장서야겠다.

10. 영적터치 (단어 또는 구절)
5절: 말씀에 의지하여 내가 그물을 내리리이다 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-05-24', '누가복음', '5장 11~20절', '', '(누가복음 5장)
11. 그들이 배들을 육지에 대고 모든 것을 버려 두고 예수를 따르니라
12.  예수께서 한 동네에 계실 때에 온 몸에 나병 들린 사람이 있어 예수를 보고 엎드려 구하여 이르되 주여 원하시면 나를 깨끗하게 하실 수 있나이다 하니
13. 예수께서 손을 내밀어 그에게 대시며 이르시되 내가 원하노니 깨끗함을 받으라 하신대 나병이 곧 떠나니라
14. 예수께서 그를 경고하시되 아무에게도 이르지 말고 가서 제사장에게 네 몸을 보이고 또 네가 깨끗하게 됨으로 인하여 모세가 명한 대로 예물을 드려 그들에게 입증하라 하셨더니
15. 예수의 소문이 더욱 퍼지매 수많은 무리가 말씀도 듣고 자기 병도 고침을 받고자 하여 모여 오되
16. 예수는 물러가사 한적한 곳에서 기도하시니라
17.  하루는 가르치실 때에 갈릴리의 각 마을과 유대와 예루살렘에서 온 바리새인과 율법교사들이 앉았는데 병을 고치는 주의 능력이 예수와 함께 하더라
18. 한 중풍병자를 사람들이 침상에 메고 와서 예수 앞에 들여놓고자 하였으나
19. 무리 때문에 메고 들어갈 길을 얻지 못한지라 지붕에 올라가 기와를 벗기고 병자를 침상째 무리 가운데로 예수 앞에 달아 내리니
20. 예수께서 그들의 믿음을 보시고 이르시되 이 사람아 네 죄 사함을 받았느니라 하시니

