2025년 5월25일 
누가복음 5장11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
병 고침/깨끗함: 12절 13절 14절 15절 17절 
예수: 12절 13절 14절 15절 16절 18절 19절 20절
무리: 15절 19절

4.주제 만들기: 
치료자 되신 예수.

5.하나님 찾기 (관찰)
나병환자를 고쳐주시는 예수.
알려지기를 원하지 않으시는 예수.
한적한 곳에 가셔서 기도히시는 예수.
중풍병자의 믿음을 보시고 그의 죄를 사해주시는 예수.

6.인간 찾기(관찰)
생업을 접고 예수를 따르는 야곱과 요한 그리고 베드로.
예수님께 병의 고침을 받기위해 다가가는 무리.
지붕을 벗기고 예수님께 다가가는 중풍병자와 그의 동료들.

7.하나님 찾기(해석)
예수님은 많은 사람들을 대상으로 말씀을 전파하시고 병자들도 치유하셨다. 

그때 많은 사람들이 소문을 듣고 예수께로 몰려왔다. 그러자 예수님의 취하신 행동은 도리어 한적한 곳으로 가셔서 기도를 하셨다. 

예수님은 사람들로부터 인기나 높아짐 보다는 하나님 과의 깊은 대화를 더욱 중요시하시는 것 같다. 

예수님은 높아지려고 목적으로 육신이 몸으로 이 땅에 오신 것이 아니라 생명을 사랑하사 죽기 위해 오셨다. 

이러한 올바른 영성은 오직 하나님의 은혜로부터 생겨남으로 개인 기도 생활이 얼마나 중요한지 알게 된다.

8. 인간 찾기(해석)
베드로 야곱 요한은 자신들의 주업의 도구인 배와 그물을 버려두고 예수를 따랐다. 

그들은 아직 믿음이 높지는 않았지만 예수님이 범상치 않은 능력자임을 느꼈을 것이라 여겨진다. 

중요한 가치를 발견하면 과감한 결단이 중요하다고 생각된다. 결국 그들은 과감한 결정으로 기독교 역사에 기억되는 위인들이 되었다.

9.적용(나):
 무엇보다도 하나님과의 깊은 기도생활에 더욱 힘써야겠다.

10. 영적터치 (단어 또는 구절)
16절: 한적한 곳에서 기도하시느니라


11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-05-25', '누가복음', '5장 21~30절', '모든 생각을 아시는 예수님, 간절한 자를 구원하시는 예수님', '[눅5:21-30]
21 서기관과 바리새인들이 생각하여 이르되 이 신성모독 하는 자가 누구냐 오직 하나님 외에 누가 능히 죄를 사하겠느냐
22 예수께서 그 생각을 아시고 대답하여 이르시되 너희 마음에 무슨 생각을 하느냐
23 네 죄 사함을 받았느니라 하는 말과 일어나 걸어가라 하는 말이 어느 것이 쉽겠느냐
24 그러나 인자가 땅에서 죄를 사하는 권세가 있는 줄을 너희로 알게 하리라 하시고 중풍병자에게 말씀하시되 내가 네게 이르노니 일어나 네 침상을 가지고 집으로 가라 하시매
25 그 사람이 그들 앞에서 곧 일어나 그 누웠던 것을 가지고 하나님께 영광을 돌리며 자기 집으로 돌아가니
26 모든 사람이 놀라 하나님께 영광을 돌리며 심히 두려워하여 이르되 오늘 우리가 놀라운 일을 보았다 하니라
27 그 후에 예수께서 나가사 레위라 하는 세리가 세관에 앉아 있는 것을 보시고 나를 따르라 하시니
28 그가 모든 것을 버리고 일어나 따르니라
29 레위가 예수를 위하여 자기 집에서 큰 잔치를 하니 세리와 다른 사람이 많이 함께 앉아 있는지라
30 바리새인과 그들의 서기관들이 그 제자들을 비방하여 이르되 너희가 어찌하여 세리와 죄인과 함께 먹고 마시느냐

