INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-05-27', '누가복음', '6장 11~20절', '열두 제자를 세우다', '누가복음 6장
11   그들은 노기가 가득하여 예수를 어떻게 할까 하고 서로 의논하니라
