13   밝으매 그 제자들을 부르사 그 중에서 열둘을 택하여 사도라 칭하셨으니
14   곧 베드로라고도 이름을 주신 시몬과 그의 동생 안드레와 야고보와 요한과 빌립과 바돌로매와
