하나님: 12, 20

4.주제 만들기: 열두 제자를 세우다

5.하나님 찾기(관찰)
- 밤이 새도록 기도하시고, 열두 제자를 세우시는 예수님
- 가난한 자는 복이 있다 말씀하시는 예수님

6.인간 찾기(관찰)
- 안식일에 사람을 고치시는 예수님을 보고 화가 나 예수님을 어떻게 할까 의논하는 서기관과 바리새인
- 예수님을 따르는 제자들과 군중들
- 예수님을 만지려고 힘쓰는 군중들

7.하나님 찾기(해석)
- 예수님께서 밤이 새도록 기도하시고 열두 제자를 임명하셨다.
- 열두 제자가 누가 될지 예수님은 미리 알고 계셨을까? 아니면 기도 후에 하나님께서 알려주셨을까?
- 무엇이 맞던 중요한 것은 예수님께서 밤이 새도록 기도하셨다는 것이다.
- 열두 제자를 세우는 중요한 일을 할 때, 그동안 지켜보니 이들이 좋더라 이들을 세우자 하고 생각하신 것이 아니라, 기도를 하셨다. 그것도 밤을 새워 기도하셨다.

- 귀신들린 자를 고치시고, 병든 자를 낫게 하셨다.
- 혈루병을 앓는 여인이 예수님의 옷자락을 만지고 나음을 입은 것처럼,
- 수많은 사람들이 예수님을 만지기만 하면 나음을 입었다.

- 예수님께서 가난한 자에게 복이 있다고 말씀하시며, 하나님 나라가 너희의 것이라 선포하신다.
- 예수님을 따르는 군중들은 대부분 가난한 자들이었다(심령이 가난한 것뿐만 아니라).
- 가난한 자들은 겸손하게 하나님의 아들이신 예수님께 나아갔다.
- 겸손함은 예수님께 나아가는, 하나님 나라에 다가가는 중요한 태도이다.
- 우리는 영적으로 겸손한 자들이 돼야 한다.

8.인간 찾기(해석)
- 유대교 기득권을 차지하고 있는 서기관들과 바리새인은 군중들이 예수님께 열광하는 것이 싫었을 것이고,
- 오랜 시간 쌓아 온 자신들의 지식과 세계관에 반대되는 일을 행하시는 예수님이 정말 싫었을 것이다.
- 그래서 그들은 이제 예수님을 어떻게 처리할까 의논을 시작한다.

- 가난한(영적 가난함/경제적 빈곤) 군중들은 예수님의 말씀을 듣고자, 병 고침을 받고자 예수님께 나아온다.
- 예수님은 가난한 자에게 복음을 전하시려고 이 땅에 오셨고, 그들이 예수님께 나아왔다.   

9.적용(나) 
- 예수님께서 제자를 세우실 때 밤이 새도록 기도하셨다.
- 평소에도 기도하셨지만, 중요한 일을 앞두고 집중 기도를 하신 것이다.
- 예수님을 본받아 말씀과 기도를 쉬지 않도록 해야 하겠고,
- 중요한 일을 앞두고는 집중하여 기도하는 것을 잊지 말아야겠다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-05-28', '누가복음', '6장 1~10절', '&nbsp;', '(누가복음 6장)
1.  안식일에 예수께서 밀밭 사이로 지나가실새 제자들이 이삭을 잘라 손으로 비비어 먹으니
2. 어떤 바리새인들이 말하되 어찌하여 안식일에 하지 못할 일을 하느냐
3. 예수께서 대답하여 이르시되 다윗이 자기 및 자기와 함께 한 자들이 시장할 때에 한 일을 읽지 못하였느냐
4. 그가 하나님의 전에 들어가서 다만 제사장 외에는 먹어서는 안 되는 진설병을 먹고 함께 한 자들에게도 주지 아니하였느냐
5. 또 이르시되 인자는 안식일의 주인이니라 하시더라
6.  또 다른 안식일에 예수께서 회당에 들어가사 가르치실새 거기 오른손 마른 사람이 있는지라
7. 서기관과 바리새인들이 예수를 고발할 증거를 찾으려 하여 안식일에 병을 고치시는가 엿보니
8. 예수께서 그들의 생각을 아시고 손 마른 사람에게 이르시되 일어나 한가운데 서라 하시니 그가 일어나 서거늘
9. 예수께서 그들에게 이르시되 내가 너희에게 묻노니 안식일에 선을 행하는 것과 악을 행하는 것, 생명을 구하는 것과 죽이는 것, 어느 것이 옳으냐 하시며
10. 무리를 둘러보시고 그 사람에게 이르시되 네 손을 내밀라 하시니 그가 그리하매 그 손이 회복된지라

