4.주제 만들기: 
안식일의 주인이신 예수.

5.하나님 찾기 (관찰)
안식일에 이삭을 취하는 제자들올 비판하는 바리새인에게 변호하시는 예수.
안식일에 회당에서 마른손 환자를 치유하시는 예수.

6.인간 찾기(관찰)
안식일에 이삭을 취하는 제자들을 정죄하는 바리새인.
예수님의 행동에 대하여 고발할 증거를 찾는 서기관과 바리새인.

7.하나님 찾기(해석)
.예수님은 안식일의 존재 목적을 분명히 설명하셨다. 

우선 안식일의 밀밭에서 이삭을 취해 먹는 제자들을 향하여 정죄하는 바리새인의 모습을 볼 수 있다. 

둘째는 안식일의 회당에서 마른 손을 가진 병자를 치료하는 것을 두고 악하다 하는 서기관과 바리새인을 알 수 있다. 

예수님은 그들의 비판과 상관없이 사랑을 베푸사 병든자를 회복시키시는 일을 행하셨다. 

안식일을 만드신 목적을 분명히 하고 계신다.

8. 인간 찾기(해석)
바리새인과 서기관은 생명을 주제로 생각하고 만들어진 안식년의 취지를 망각한 체 오직 자신들의 기득권을 취하기 위하여 예수님을 비난하고 있다. 

9.적용(나):
 다른 사람을 평가하는 사람이 아닌 사랑하는 사람이 되야겠다.

