4. 주제만들기: 예수님께서 놀란 백부장의 믿음

5. 하나님 찾기 (관찰)
- 백부장의 말을 들으시고 놀라시는 예수님

6. 인간 찾기 (관찰)
- 종이 병에 걸려 예수님을 찾아가 낫게 해달라고 요청하는 백부장
- 백부장에 대해 말해주는 유대인의 장로들
- 예수님이 들어오심을 감당하지 못하겠다고 고백하는 백부장, 말씀만으로 종이 나을 것을 믿는 백부장

7. 하나님 찾기 (해석)
- 예수님은 간절한 요청에 백부장의 종을 고쳐주고자 하셨다. 그의 집에 방문하려 할 때 백부장의 고백을 듣고 백부장의 믿음에 깜짝 놀라시며, 이스라엘에서 그만한 믿음을 보지 못했다고 말씀하셨다.
- 하나님은 우리의 중심을 보신다. 백부장이 가진 믿음이 어떠한 결과를 보여주는지 우리에게 알려주신다.

8. 인간(해석):
- 유대인의 장로들이 직접 나서서 백부장에 대해 예수님께 간절히 구한 것으로 보아 그가 어떤 삶을 살았고, 어떠한 성품인지 알 수 있다.
- 백부장은 예수님의 방문에 감당하지 못한다는 말고 예수님의 권세와 능력을 인정하고 자신을 낮추는 겸손함까지 보여주었다.
- 말씀만으로 종이 나을 수 있다는 믿음의 고백은 예수님을 놀라게까지 하였다. 
- 우리가 갖추어야 할 성품과 믿음이다.

9. 적용(나): 
- 우리의 믿음을 더욱 굳건하게 해주시도록 기도해야겠다.
- 예수님께서 놀라시는 믿음의 삶을 살아가야겠다.

