4.주제 만들기: 과부의 외아들을 살리심

5.하나님 찾기(관찰)
- 예수님께서 과부를 보시고 불쌍히 여기사 아들을 살려주심

6.인간 찾기(관찰)
- 예수님을 따르는 제자들과 많은 무리
- 상여를 뒤따르는 과부와 많은 사람
- 살아난 외아들
- 예수님이 죽었던 청년을 살리신 것에 대해 침례 요한에게 전하는 요한의 제자들

7.하나님 찾기(해석)
- 예수님은 외아들을 잃은 과부를 불쌍히 여기시고 울지 말라 하셨다.
- 상여를 뒤따르는 과부의 딱한 사정을 잘 아셨을 뿐만 아니라,
- 외아들을 잃은 과부에게 울리 말라 하셨다.
- 아마도 그 과부가 절망에 빠져 울고 있는 모습이 예수님의 마음을 아프게 했던 것 같다.
- 나아가 잃어버린 양들을 애타게 찾는 하나님의 마음이, 
- 외아들을 잃은 과부의 마음과 비슷했는지도 모르겠다.

- 청년아 일어나라 명하시고 일어나자 과부에게 돌려주셨다.
- 사망도 예수님의 명령 앞에서는 물러날 수 밖에 없다.

8.인간 찾기(해석)
- 예수님의 기적을 보고 따라온 많은 무리도,
- 과부와 많은 사람도 죽은 자가 예수님 명령에 일어나는 것을 보고 경이로움을 느겼을 것이다.
- 이 기적은 지금까지의 기적과는 다른 차원의 것이었다.

- 침례 요한의 제자들이 그 자리에 있었는지, 소문을 들었는지 모르겟으나,
- 그 기적에 대해 침례 요한에게 이야기함
- 놀라운 소식을 들은 침례 요한은 예수님이 메시아임을 확신하게 되었고,
- 제자들을 예수님께 보내어 메시아가 맞는지, 아니면 다른 분을 기다려야 하는지 확인하게 함.

9.적용(나) 
- 예수님이 잃어버린 양들이 돌아오길 간절히 바라시며 슬피 울고 계실 것만 같다.
- 힘을 내어 보내신 곳에서 전도를 해야겠다.

