4.주제 만들기: 바리새인과 죄를 지은 한 여자 

5.하나님 찾기(관찰)
- 이 세대의 사람(특히, 요한의 세례를 받지 않은 바리새인)을 장터의 아이들을 비유로 들어 말씀하심
- 배리새인의 집에 앉으심

6.인간 찾기(관찰)
- 한 바리새인이 예수님을 자기 집으로 초대함
- 죄를 지은 한 여자가 예수님의 발에 입맞추고 향유를 부음

7.하나님 찾기(해석)
- 하나님께서 침례 요한을 예수님 앞에 보내셨으나 이 세대의 사람들이 요한의 침례를 받지 않은 것에 대해 장터의 아이들 비유로 말씀하심
- 그들이 침례 요한도 예수님도 각각 다른 이유로 비난하며 따르지 않은 것을 지적하심
- 그 세대의 바리새인들은 권력과 자신들이 쌓은 지식에 취해 있던 것으로 보임

8.인간 찾기(해석)
- 죄를 지은 한 여인이 눈물로 예수님의 발을 적시고 머리털로 발을 닦고 발에 입 맞추고 향유를 부었다
- 그 여인은 귀신 들렸었거나 불치병에 걸렸었거나 간음했던 사람이었고
- 예수님께서 그 여인을 낫게(용서) 해주셨을 것이다.
- (어쩌면 그 여인은 예수님이 메시아 되심을 깨달았는지도 모른다.)
- 그래서 너무나 감사해서 예수님을 찾아가 감사드리며 감격의 눈물을 흘리며 그렇게 했을 것이다.

- 한편 바리새인은 그 순간 예수님이 선지자라면 저 여자가 죄인인 것을 알았으리라 생각하며 예수님을 마음으로 얕잡아 봄

9.적용(나) 
- 복음을 비판할 사람들은 어떤 이유를 들어서든 비판할 것이다.
- 그들의 비판 여부를 떠나서 나는 예수님을 따라 복음을 전하면 그만이다.
- ‘너희가 피곤하여 낙심하지 않기 위하여 죄인들이 이같이 자기에게 거역한 일을 참이신 이를 생각하라’ 히 12:3  

