4. 주제만들기: 예수님의 명령을 따르기 필요한 완전한 믿음

5. 하나님 찾기 (관찰)
- 호수 저편으로 건너가자 말씀하신 예수님
- 배를 타고 이동 중에 잠드신 예수님
- 제자들의 요청에 일어나 바람과 물을 꾸짖으신 예수님
- 제자들의 믿음에 대해 말씀하신 예수님
- 거라사인에서 귀신을 만나 나오게 하심
- 귀신에게 이름이 무엇이냐 묻는 예수님

6. 인간 찾기 (관찰)
- 제자들의 예수님의 명령에 순종하여 호수 건너편으로 가는 배를 탔다.
- 광풍을 만나자 두려움에 예수님을 깨워 상황을 전달했다.

7. 하나님 찾기 (해석) 
- 예수님께선 호수 저편으로 건너가자 말씀하셨다. 예수님께서 말씀하셨다는 것은 예수님께서 반드시 이루신다는 것이다. 제자들의 상황에선 호수 저편으로 반드시 갈 수 있다는 말이다. 
- 광풍에 놀라 예수님을 깨우는 제자들을 책망하신 예수님은 하나님의 언약이 반드시 이루어짐을 알려주고 싶으셨을 것이다. 

8. 인간(해석):
- 제자들은 호수 저편으로 가자는 예수님의 명령에 순종했다. 
- 많은 기적을 만드시는 예수님과 함께하는 것이 즐겁고, 영광스러웠을 것이다. 
- 그러나 예기치 못한 광풍을 만나자 예수님을 깨웠다. 예수님께서 믿음이 어디있느냐라고 여쭤보신 것으로 보아, 당신을 따라 왔는데 이게 어떻게 된 일이냐와 같은 생각을 했을 것 같다.
- 하나님께서 분명히 말씀하시는 일에는 완전한 믿음이 필요하다. 그 길을 따라가는 가운데 일어나는 여러 풍파는 하나님께서 우리를 단련시키는 과정이다. 
- 내게 온전한 믿음이 필요함을 깨닫는다. 

9. 적용(나): 
- 하나님을 의지한다는 것을 말로만 하는 것이 아니라 믿음으로 이루고 싶다. 하나님을 온전히 믿는 믿음이 내 안에 가득 임하길 기도해야겠다.

10. 영적터치(단어/구절)
- 호수 저편으로 건너가자

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-06-09', '누가복음', '8장 31~40절', '군대 귀신 들린 자를 고치시다', '누가복음 8장
31   무저갱으로 들어가라 하지 마시기를 간구하더니
32   마침 그 곳에 많은 돼지 떼가 산에서 먹고 있는지라 귀신들이 그 돼지에게로 들어가게 허락하심을 간구하니 이에 허락하시니
33   귀신들이 그 사람에게서 나와 돼지에게로 들어가니 그 떼가 비탈로 내리달아 호수에 들어가 몰사하거늘
34   치던 자들이 그 이루어진 일을 보고 도망하여 성내와 마을에 알리니
35   사람들이 그 이루어진 일을 보러 나와서 예수께 이르러 귀신 나간 사람이 옷을 입고 정신이 온전하여 예수의 발치에 앉아 있는 것을 보고 두려워하거늘
36   귀신 들렸던 자가 어떻게 구원 받았는지를 본 자들이 그들에게 이르매
37   거라사인의 땅 근방 모든 백성이 크게 두려워하여 예수께 떠나가시기를 구하더라 예수께서 배에 올라 돌아가실새
38   귀신 나간 사람이 함께 있기를 구하였으나 예수께서 그를 보내시며 이르시되
39   집으로 돌아가 하나님이 네게 어떻게 큰 일을 행하셨는지를 말하라 하시니 그가 가서 예수께서 자기에게 어떻게 큰 일을 행하셨는지를 온 성내에 전파하니라
40   예수께서 돌아오시매 무리가 환영하니 이는 다 기다렸음이러라

