4.주제 만들기: 군대 귀신 들린 자를 고치시다

5.하나님 찾기(관찰)
- 군대 귀신이 돼지 떼에게 들어가는 것을 허락하심
- 거라사인 주민들이 떠나시기를 구하매 배를 타고 떠나심
- 군대 귀신이 나감을 받은 사람이 예수님과 함께 있기를 구했으나, 
- 예수님은 집으로 가서 하나님이 하신 큰 일을 말하라 명하심

6.인간 찾기(관찰)
- 군대 귀신 들린 자가 나음을 받음
- 온전해진 자가 예수님의 발치에 앉았음
- 돼지 치던 자들이 돼지 떼가 몰사는 것을 보고 마을로 내려가 사람들에게 본 것을 모두 말함 
- 마을 사람들이 올라와 귀신 들렸던 자가 온전해진 것을 보고 두려워함
- 귀신 들렸던 자가 어떻게 나음을 입었는지 모든 사람에게 말함
- 이 이야기를 들은 자들이 두려워 예수님께 떠나시기를 구함
- 귀신 들렸던 자가 예수님께 함께 있고 싶다고 말함
- 그러나 예수님은 집으로 가서 전하라 하셨고,
- 이 사람은 자기 집과 온 성내에 전파함

7.하나님 찾기(해석)
- 군대 귀신 들린 자를 불쌍히 여기시고 귀신을 쫓아내심
- 귀신은 안심하며 돼지 떼에게 들어갔으나, 그 결국은 모두 죽는 것이있다.

- 마을 사람들이 예수님을 두려워하며 떠나시기를 구하자,
- 좋은 것을 주려 오셨던 예수님은 그들이 구하는 대로 그곳을 떠나심

- 예수님은 귀신 들렸던 자가 함께 가겠다고 하는 것을 막으시고,
- 네 집으로 가라 그리고 하나님이 네게 행한 큰 일을 전하라고 명하셨다.
- 내가 바라는 것과 예수님이 바라는 것에는 차이가 있을 수 있다.
- 잘 느끼고 순종해야 한다.
- 예수님은 자기가 한 일이 아니라, 하나님이 하신 일이라고 겸손하게 말씀하셨다.

8.인간 찾기(해석)
- 마을 사람들이 귀신 들린 자가 온전해 진 것과 돼지 떼가 몰사한 것을 듣고 크게 두려워함
- 예수님은 복음을 들고 오셨고, 구원을 베푸시는데, 이 마을 사람들은 예수님을 두려워하며 떠나시기를 구함
- 예수님의 놀라운 능력과 구원을 보고도 자신들의 유익을 위해 예수님을 떠나라고 하는 것을 보면, 사람들의 생각과 욕망이 얼마나 어리석은 것인지 생각해 보게 된다.

- 귀신 들렸던 자는 예수님을 따라가고 싶었다. 아마도 예수님께 너무나 감사하고, 이 분이 바로 그리스도이심을 깨달았기 때문일 것이다.
- 그러나 예수님은 이 사람을 집으로 가라 명하셨고,
- 그는 순종하여 자기 집으로 가 온 성읍에 예수님의 능력으로 깨끗함을 입었음을 전하였다.
- 그는 자신의 체험을 열정적으로 전파했을 것이며, 온 성읍 사람들은 예수님이 바로 그리스도시라고 전파하는 그의 말을 듣게 되었을 것이다.
- 아마도 그는 큰 전도자가 되었을 것이다.

9.적용(나) 
- 예수님이 좋아 날마다 예수님을 예배하며 살고 싶었다.
- 그러나 세상에 일이 많으니, 가서 일하라는 예수님의 마음을 알게 되었다.
- 그곳이 지금 있는 곳인지 다른 곳인지 나는 아직 알지 못하나,
- 그 말씀에 순종하여 보내진 곳에서 열심히 일하며, 내가 체험한 예수님을 전해야겠다.

10.영적 터치(단어/구절)
  39   집으로 돌아가 하나님이 네게 어떻게 큰 일을 행하셨는지를 말하라 하시니 그가 가서 예수께서 자기에게 어떻게 큰 일을 행하셨는지를 온 성내에 전파하니라

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-06-10', '누가복음', '8장 41~50절', '&nbsp;', '(누가복음 8장)
41. 이에 회당장인 야이로라 하는 사람이 와서 예수의 발 아래에 엎드려 자기 집에 오시기를 간구하니
42. 이는 자기에게 열두 살 된 외딸이 있어 죽어감이러라 예수께서 가실 때에 무리가 밀려들더라
43. 이에 열두 해를 혈루증으로 앓는 중에 아무에게도 고침을 받지 못하던 여자가
44. 예수의 뒤로 와서 그의 옷 가에 손을 대니 혈루증이 즉시 그쳤더라
45. 예수께서 이르시되 내게 손을 댄 자가 누구냐 하시니 다 아니라 할 때에 베드로가 이르되 주여 무리가 밀려들어 미나이다
46. 예수께서 이르시되 내게 손을 댄 자가 있도다 이는 내게서 능력이 나간 줄 앎이로다 하신대
47. 여자가 스스로 숨기지 못할 줄 알고 떨며 나아와 엎드리어 그 손 댄 이유와 곧 나은 것을 모든 사람 앞에서 말하니
48. 예수께서 이르시되 딸아 네 믿음이 너를 구원하였으니 평안히 가라 하시더라
49. 아직 말씀하실 때에 회당장의 집에서 사람이 와서 말하되 당신의 딸이 죽었나이다 선생님을 더 괴롭게 하지 마소서 하거늘
50. 예수께서 들으시고 이르시되 두려워하지 말고 믿기만 하라 그리하면 딸이 구원을 얻으리라 하시고

