4.주제 만들기: 죽은 아이를 살리시는 예수님 

5.하나님 찾기(관찰)
- 베드로와 야고보, 요한, 그리고 아이의 부모만 집으로 들어오게 함
- 아이가 죽은 것이 아니라, 자는 것이다 라고 말씀하심
- 아이의 손을 잡고 불러 살리시고, 먹을 것을 주라 명하심
- 이 일을 아무에게도 말하지 말라 명하심

6.인간 찾기(관찰)
- 제자 중에서 베드로와 야고보, 요한, 이 세 사람만이 방에 들어가는 것을 허락받았다.
- 사람들이 죽은 것이 아니라 잔다는 예수님의 말씀을 비웃음 
- 세 제자와 아이의 부모가 아이가 살아나는 것을 목격한다.
- 아이가 살아나고, 먹을 것을 먹었다.

7.하나님 찾기(해석)
- 제자 중에서 세 제자만 들어오게 하셨는데,
- 아마도 이 세 제자는 예수님을 더욱 사랑하는 자들이며, 믿음이 더욱 견고한 자들이었던 것으로 생각된다.
- 죽은 아이를 잔다고 하시며, 살리심
- 예수님은 부활이요, 생명이시다.
- 예수님이 계시기에 우리 신자들의 죽음은 죽음이 아니라, 잠시 자는 것이다.
- 아이가 살아난 것을 알리지 말게 하셨는데,
- 아마도 많은 사람들이 알게 될 경우 소란한 일이 발생할 수 있기 때문에 방지 차원에서 그렇게 하셨을 것으로 생각한다.

8.인간 찾기(해석)
- 세 제자는 예수님이 자기들만 부르셨을 때 정말 기뻤을 것이다.
- 사람들은 예수님을 비웃었다.
- 예수님의 능력을 익히 듣고 알았음에도,
- 자신들이 물리적으로 분명히 죽은 것을 안다는 생각에 예수님을 비웃었다.
- 기적은 내 생각과 상식을 뛰어넘는 것이다.
- 오늘날 과학이 발달하여 많은 사람들이 기독교를 비과학적이라고 비판하는데,
- 과학이 뒤집히는 것도 과학이 발견하는 것도 
- 모두다 하나님이 하시는 것임을 그들도 언젠가 알게 될 것이다.
 
- 아이가 살아나는 것을 지켜본 부모는 정말 놀랍고 기뻤을 것이다.
- 그 놀라움은 사람의 말로는 표현할 수 없는 놀라움이다. 

9.적용(나) 
- 자신을 비웃는 사람들에게 크게 대응하지 않으시고,
- 묵묵히 생명을 살리신 예수님을 닮고 싶다.
- 사람들이 내게 무례하게 대하고, 나를 비웃으면 나는 화가 많이 나는데,
- 예수님은 어떻게 자기를 거절한 사람들을 참으시고 십자가를 지셨는지 그 놀라운 사랑을 이해하기 어렵다.
- 내 머리로는 이해할 수 없는 예수님의 은혜에 감사할 따름이다.

