4.주제 만들기: 
오병이어의 기적을 베푸신 예수.

5.하나님 찾기 (관찰)
오병이어의 기적을 행하신 예수.
따로 기도히시는 예수.
자신에 대하여 물으시는 예수.

6.인간 찾기(관찰)
예수를 따르는무리.
예수의 질문에 답하는 제자들:
