베드로:
예수는 하나님의 그리스도 라고 함.

7.하나님 찾기(해석)
예수님은 오병이어의 기적을 베푸셨다. 

남자 성인만 5천 명이었던 것을 생각하면 아이들과 여성들까지 포함한다면 아마 만 명은 족히 넘었을 것이다. 

예수님이 놀라운 능력을 행하실 때 하늘을 우러러 축사하셨다. 

오병이어의 기적 후에는 따로 조용히 기도 자리로 가신 부분이다. 인기가 최고조로 올라갈 때 그 즐거움을 즐기기보다 기도로 하나님과 만나시기 위해 힘쓰신 것 같다. 

하나님 자신이신 예수님께서 늘 하나님을 인식하시는 모습을 보이셨다. 

예수님도 그렇게 행하셨는데 피조물인 인간이 하나님을 의지하거나 인식하지 않고 사역을 한다는 것은 이미 실패를 준비하는 것이 확실하다. 

또한 예수님께서 이 땅에 오신 목적은 단지 인기를 누리기 위해 오신 것이 아닌 죽기까지 사랑하사 영혼 구원을 위해 오신 목적을 생각할 때 충분히 예수님의 사랑을 깨우치게 된다.

8. 인간 찾기(해석)

9.적용(나):
남북 청년연합 선교회에서 사역할 때든지 전후에도 늘 하나님과 깊은 독대 시간을 더욱 가져야겠다. 

혹시 열매를 통하여 인기가 생기더라도 겸손한 마음으로 하나님께만 영광을 올리도록 힘써야겠다.

10. 영적터치 (단어 또는 구절)
20절: 너희는 나를 누구라 하느냐

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

