3. 반복단어 찾기(형광펜 추천)
- 두사람(32,33절)
- 예수(31,32,33,36절)
- 소리(35,36절)

4. 주제만들기: 하나님의 아들로 택함을 받은 예수님

5. 하나님 찾기 (관찰)
- 모세와 엘리야가 나타나 예수님이 예루살렘에서 별세하실 것을 말함
- 구름속으로 나타나 말씀하시는 하나님

6. 인간 찾기 (관찰)
- 베드로는 깊이 졸다 깨어 변화된 예수님과 모세, 엘리야를 보고 초막 셋을 짓자고 말함
- 베드로는 자신이 한 말을 자신도 알지 못함
- 구름속으로 들어갈 때 두려워하는 제자들, 자신들이 본 것을 말하지 않음

7. 하나님 찾기 (해석) 
- 변화산에 나타난 모세와 엘리야를 통해 예수님이 율법과 선지자를 폐하러 오신 것이 아니라 완전하게 하러 오신 것임을 드러내셨다.
- 어린양의 죄사함을 경험한 모세와 회개와 심판, 구원의 상징인 엘리야의 등장은 예수님의 구속 사역을 확증한 것이다. 

8. 인간(해석):
- 베드로와 제자들은 예수님이 변화된 순간 깊은 잠이 들었다 깨어나 모세와 엘리야의 모습을 보게 되었다. 자신이 무슨 말을 했는지 모를 정도로 깊이 잠들었다.
- 그렇기 때문에 모세와 엘리야가 말한 예수님의 십자가 죽음을 허투루 들었을 것이다.
- 오히려 자신들이 본 모세와 엘리야의 모습을 영웅담 다루듯이 함께하는 제자들에게 자랑했을 수도 있다.(내 생각)
- 하나님께선 예수님의 십자가 죽음을 말씀하시는데, 인간은 그것을 깨닫지 못했다. 
- 육으로나 영으로나 깨어 있는 것이 중요하다는 것을 깨닫는다. 
- 지금 이 순간에도 하나님께선 예수님의 십자가 사랑을 말하고 계시는데 나는 깨닫지 못하고 있을 수 있다. 

9. 적용(나): 
- 예수님께서 이루신 사랑을 매일, 매시간 생각하며 육으로 영으로 건강한 상태를 유지하는 것이 중요하다. 말씀과 기도, 전도에 힘써야겠다.

10. 영적터치(단어/구절)
- 깊이 졸다가 온전히 깨어나

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

