4. 주제만들기: 

5. 하나님 찾기 (관찰)
- 그 날에 대해 말씀하시는 예수님
- 70인에게 권능을 주시는 예수님
- 귀신이 항복하는 것에 기뻐하지 말고, 하늘에 이름이 기록된 것에 기뻐하라 하시는 예수님

6. 인간 찾기 (관찰)
- 귀신을 쫓는 권능을 받고 실제 귀신을 쫓자 기뻐하는 70인

7. 하나님 찾기 (해석) 
- 예수님은 그날에 소돔이 그 동네보다 견디기 쉽다고 말씀하시며, 예수님이 주로 사역을 한 동네인 고라신과 뱃새다와 가버나움의 복음을 받아들이지 못하고 회개하지 않는 행태에 대해 말씀하셨다. 
- 복음을 먼저 받아들였거나, 알더라도 그것을 지키지 못하거나, 깨닫고 회개하지 않는다면 무익한 일임을 다시 생각하게 된다. 
- 이런 어리석은 행동을 하는 것이 나이고, 우리다. 항상 겸손함으로 하나님의 말씀을 바르고 온전하게 받아들이고 전할 수 있어야 한다.
- 예수님께선 우리에게 뱀과 전갈을 밟으며 원수의 모든 능력을 제어할 권능을 주셨다. 그러나 우리는 예수님께서 주신 권능을 올바로 사용하지 못하고 있다. 그 가운데는 교만함이 작용하고 있을 것이다.

8. 인간(해석):
- 선택받은 70인은 예수님으로부터 권능을 받았다. 70인은 자신들이 귀신을 쫓아내는데에 집중했다. 그러나 예수님은 70인의 이름이 하늘에 기록된 것을 기뻐하라 하셨다. 
- 우리는 눈앞에 보이는 현상에 집중하지만 예수님은 하늘 나라에 소망을 보라 말씀하신다. 
- 나는 이 시대에서 잘 살고 싶고, 좋은 집과 훌륭한 자녀들을 바라지만 하나님께선 하늘 나라의 소망을 보라 말씀하신다.
- 내가 집중해야 할 것은 이 땅이 아닌 하늘 나라다. 하늘나라의 소망을 위해 하나님께선 무엇을 원하시는지, 무엇에 더 힘써야 할지 고민하고 찾고 행동하도록 노력해야 한다. 

9. 적용(나): 
- 권능을 주신 하나님께 감사하며, 권능을 바르게 사용할 수 있도록 영성이 길러지길 소망한다.
- 하늘나라의 소망을 두고 하나님의 일에 더욱 집중하고 그 일을 잘하기 위해 노력해야겠다.

10. 영적터치(단어/구절)
- 19 내가 너희에게 뱀과 전갈을 밟으며 원수의 모든 능력을 제어할 권능을 주었으니 너희를 해칠 자가 결코 없으리라

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-06-20', '누가복음', '10장 21~30절', '&nbsp;', '(누가복음 10장)
21.  그 때에 예수께서 성령으로 기뻐하시며 이르시되 천지의 주재이신 아버지여 이것을 지혜롭고 슬기 있는 자들에게는 숨기시고 어린 아이들에게는 나타내심을 감사하나이다 옳소이다 이렇게 된 것이 아버지의 뜻이니이다
22. 내 아버지께서 모든 것을 내게 주셨으니 아버지 외에는 아들이 누구인지 아는 자가 없고 아들과 또 아들의 소원대로 계시를 받는 자 외에는 아버지가 누구인지 아는 자가 없나이다 하시고
23. 제자들을 돌아 보시며 조용히 이르시되 너희가 보는 것을 보는 눈은 복이 있도다
24. 내가 너희에게 말하노니 많은 선지자와 임금이 너희가 보는 바를 보고자 하였으되 보지 못하였으며 너희가 듣는 바를 듣고자 하였으되 듣지 못하였느니라
25.  어떤 율법교사가 일어나 예수를 시험하여 이르되 선생님 내가 무엇을 하여야 영생을 얻으리이까
26. 예수께서 이르시되 율법에 무엇이라 기록되었으며 네가 어떻게 읽느냐
27. 대답하여 이르되 네 마음을 다하며 목숨을 다하며 힘을 다하며 뜻을 다하여 주 너의 하나님을 사랑하고 또한 네 이웃을 네 자신 같이 사랑하라 하였나이다
28. 예수께서 이르시되 네 대답이 옳도다 이를 행하라 그러면 살리라 하시니
29. 그 사람이 자기를 옳게 보이려고 예수께 여짜오되 그러면 내 이웃이 누구니이까
30. 예수께서 대답하여 이르시되 어떤 사람이 예루살렘에서 여리고로 내려가다가 강도를 만나매 강도들이 그 옷을 벗기고 때려 거의 죽은 것을 버리고 갔더라

