4.주제 만들기: 
율법교사를 가르치시는 예수.

5.하나님 찾기 (관찰)
예수의 감사 기도.
율법교사에게 영생에 대하여 가르치시는 예수.

6.인간 찾기(관찰)
예수님을 시험하는 율법교사
(영생에 대하여 테스트함)

7.하나님 찾기(해석)
과거에 많은 선지자와 임금들은 직접 보고 싶어도 보지 못하고 듣고 싶어도 듣지 못했던 주인 되신 예수님은 이 땅에 등장하셨다. 

그런데도 율법 교사는 예수님을 알아보지 못하고 시험하기 위한 불순한 목적으로 질문을 하였다. 

내용은 ''영생''에 대한 것이었다. 율법 교사는 어떻게 하면 영생을 취할 수 있는지 스스로가 답은 명확히 알고 있었다. 

그러나 행함이 없음을 아신 예수께서 그에게 알려주셨다. 율법 교사는 진리에 대하여 이론적으로는 알지언정 그 말씀대로 따르지 못한 어리석은 사람임을 알 수 있다. 

무엇보다 전 인류의 주인이시고 창조자이신 ''구원자'' 되신 예수를 직접 대면하면서도 알아보지 못하는 무익한 율법 교사임을 발견할 수 있다.

이 시대에 예수님의 말씀으로 자신의 배를 채우고 인기를 얻는 신학 교수나 학자 그리고 목회자들이 많음을 더 이상 변명할 수 없는 세상이 되었다. 

많은 안타까운 일이지만 그 잘못된 부분을 성경을 통하여 회개하고 고쳐나갈 기회가 아직 있다는 것에 대하여 하나님께 큰 자비와 사랑을 느낀다.

8. 인간 찾기(해석)

9.적용(나):
말씀대로 행하는 종이 되도록 힘써야겠다.

