4.주제 만들기: 
좋은 선택

5.하나님 찾기 (관찰)
예수님은 진정한 ''이웃''이 누구인지 가르쳐 주심.
좋은 편을 택한 마리아를 칭찬하시는 예수.

6.인간 찾기(관찰)
예수님을 맞이하는 마르다와 마리아.
마리아는 예수님 곁에서 말씀을 경청하는  대신 언니 마르다는 분주하게 일함.

7.하나님 찾기(해석)

8. 인간 찾기(해석)
예수님은 자신을 시험하는 율법 교사에게 진정 이웃을 사랑하는 사람의 태도에 대하여 가르치셨다. 

내용으로는 강도를 만나 곤경에 처한 사람을 끝까지 돌보아준 평소 유대인들에게 무시당하는 사마리아 사람이야말로 진정한 이웃이라 말씀하셨다. 

반면 유대인으로부터 평상시 존경받고 있는 종교 지도자들은 그 불쌍한 처지에 놓인 사람을 보고도 방치한 채 피하였다. 

분명 예수님은 좋은 편을 선택한 착한 사마리아 사람을 칭찬한다고 볼 수 있겠다.

가르침 이후에 예수님은 또 한 번의 좋은 편을 선택함을 가르치신다. 한 마을에 자신을 섬기고자 하는 자매들이 있었는데 언니 마르다와 동생 마리아였다. 

동생 마리아는 예수님의 말씀을 듣기 위해 가까이 있는 반면에 언니 마르다는 예수님을 섬길 음식을 준비하기 분주하였다. 

이러한 모습 중 예수님은 마리아의 태도를 더욱 올바른 태도라고 칭찬하셨다.

나는 크게 두 사건(착한 사마리아인, 마르다와 마리아)을 보면서 예수님은 단지 ''행함''보다는 ‘바른 선택’을 더욱 강조하시려고 하는 것 같다고 생각했다. 

만약 행함만을 강조하였다면 마르다가 칭찬받아야 하지 않았을까?
사람들은 일상생활 가운데 빈번히 일어나는 사건과 맞닥뜨릴 때가 있는 데 더 나은 선택을 한다는 것은 누구에게나 매우 중요한 일일 것이다. 

특별히 주님 안에서 바른 선택을 하기 위해서는 더욱 주님의 영광을 위한 것인가를 생각하는 것이 좋은 선택이라 여겨진다. 

그러기 위해서는 먼저 하나님을 진심으로 사랑하려고 할 때 옳은 선택을 하지 않을까 생각해 본다.

9.적용(나):
늘 마음의 좋은 선택을 해야겠다. 그러므로 항상 주님께 기도하고 말씀묵상에 더욱 힘써야겠다.

10. 영적터치 (단어 또는 구절)
42절: 좋은 편을 택하였으니

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

