4.주제 만들기: 하나님 나라가 임하다

5.하나님 찾기(관찰)
- 하나님은 구하는 자에게 성령은 주신다
- 벙어리 귀신을 내쫓는 예수님
- 너희의 아들들은 어떻게 귀신을 내쫓느냐 물으시며 변론하시는 예수님
- 하나님 나라가 임했다라고 선포하시는 예수님

6.인간 찾기(관찰)
- 어떤 사람들이 벙어리 귀신을 내쫓은 예수님을 보고 바알세불을 힘 입어 귀신을 쫓아다고 말함
- 어떤 사람들은 예수님께 하늘에서 오늘 표적을 구함

7.하나님 찾기(해석)
- 하나님은 구하는 자에게 성령을 주신다.
- 우리 믿는 자들은 성령을 충만히 주시길 기도해야 한다. 하나님은 기도하면 주신다.
- 벙어리 귀신을 내쫓으셨는데,
- 사람들이 바알세불의 힘으로 귀신을 내쫓았다고 말하자,
- 그러면 마귀의 나라가 어떻게 유지 되겠느냐 물으시고,
- 또 너희 아들들은 누구를 힘 입어 귀신을 내쫓느냐 물으시며 변론하심
- 그리고 만일 하나님의 능력을 힘 입어 귀신을 내쫓은 것이라면 하나님 나라가 이미 너희에게 임했다라고 선포하신다.
- 아멘. 하나님 나라는 이미 임했다. 우리는 믿기만 하면 된다. 

8.인간 찾기(해석)
- 예수님께서 수많은 기적을 베푸셨지만,
- 예수님을 모함하고 비하하는 사람들이 있다.
- 그의 능력을 두 눈으로 보았음에도 그렇다.

- 예수님의 능력을 아는 것과 예수님을 하나님의 아들로 믿는 것은 별개의 것이다.
- 그들은 할 수만 있다면 예수님의 마귀와 한 패라고 유언비어를 퍼뜨리는 자들이다.
- 우리 신자들도 사람들의 말과 행동을 조심해야 한다.
- 예수님을 따르는 우리를 해하려는 자들도 분명히 있다.

9.적용(나) 
- 예수님의 능력을 보고도 예수님을 비하하고 마귀와 한 패라고 이야기 하는 사람들이 있다.
- 예수님을 따르는 나도 어떤 모함과 비방을 들을 수 있다는 것을 기억해야 한다.
- 어떤 일을 당할 때 예수님처럼 의연하게 대처하며 담대히 복음을 전해야 한다.
- 이것은 어쩌면 당연히 일어날 일이다.

