4. 주제만들기: 구하라, 찾으라, 두드리라

5. 하나님 찾기 (관찰)
- 예수님은 제자의 요청에 기도하는 법을 알려주신다.
- 예수님은 하나님의 속성에 대해 알려주신다.

6. 인간 찾기 (관찰)
- 제자 중 한명이 예수님께 기도하는 방법을 가르쳐 달라 요청함

7. 하나님 찾기 (해석) 
- 예수님은 제자의 요청에 기도하는 방법을 구체적이고 실제적인 형태로 알려주셨다. 
- 사실 이 기도문이면 우리의 기도는 완성된다. 
- 하나님께 영광을 올리고, 잘못을 회개하며, 필요를 구하고, 악에서 보호받도록 하는 기도는 모두에게 적용되고 매우 심플한 구조이다.
- 그러나 인간은 연약한 존재이므로 예수님은 구체적인 필요를 요구하는 기도도 가능함을 알려주셨다. 
- 두가지를 생각해볼 수 있다. 첫 번째는 하나님께선 간절히 요청하면 들어주시는 분이다. 그러므로 꾸준하고 끈기있는 기도의 자리가 중요하다. 두 번째는 구하고 찾고 두드리는 방법이다. 
- 구하는 것은 기도이다. 찾는 것은 하나님의 뜻을 찾는 것이다. 이것은 말씀으로 찾을 수 있다. 세 번째는 두드리는 것이다. 두드리는 것은 실제적인 행위인데 사람마다 방식은 다를 수 있다. 
- 그럼 나에게는 실제적인 행위는 무엇일까? 그것은 전도다. 매주 전도의 자리를 지키며 구하고 찾는 노력을 꾸준히 한다면 하나님과 더 가까워질 것이다. 

