6.인간 찾기(관찰)
예수님을 시험하는 무리

7.하나님 찾기(해석)
예수님은 인간에게 보일 것은 요나의 표적밖에 없다고 말씀하셨다. 왜 그렇게 말씀하셨을까? 

인간을 창조하신 주님께서 누구보다도 인간의 속성을 알고 계신다. 인간은 표적을 구하기를 원하며 그것으로 능력의 신 즉 자신을 이끌고 지켜줄 능력자를 원하고 있다. 

하지만 주님은 인간의 기대와 다르게 요나의 표적같이 스스로 죽임을 당하여 구원의 제물이 되시는 길을 선택하셨다. 

더 나아가 3일 동안 스올(지옥)에 가셨다. 절대적인 주님의 희생과 사랑을 의미한다 생각한다. 

귀신을 쫓는 일 그리고 처녀의 몸으로 잉태하는 기적보다 십자가의 사랑이 훨씬 위대함을 느낄 수 있다.

8. 인간 찾기(해석)

9.적용(나):
어떠한 표적보다 위대하신 주님의 십자가의 사랑에 감사해야겠다.

10. 영적터치 (단어 또는 구절)
29절: 요나의 표적밖에는 보일 표적이 없나니

