1.1분기도
2.본문성경 읽기(3번)
3.반복단어(같은의미 단어)
심판: 31, 32
솔로몬: 31(2)
정죄: 31, 32
더 큰 이가 여기: 31, 32
등불: 33, 34, 36
빛: 33, 35, 36
눈: 34(2)
바리새인: 37, 38, 39
겉: 39, 40
