4.주제 만들기: 몸의 등불, 네 속의 빛

5.하나님 찾기(관찰)
- 이 세대 사람이 정죄 받을 것이라 말씀하시는 예수님
- 몸의 등불은 눈이라 말씀하시고,
- 네 속에 있는 빛이 어둡지 아니한가 보라고 말씀하심
- 한 바리새인의 청을 받고 그의 집에 들어가신 예수님

6.인간 찾기(관찰)
- 바리새인이 예수님을 자기 집에 청함
- 예수님이 식사 전에 손 씻지 않음을 보고 이상히 여김

7.하나님 찾기(해석)
- 지혜의 왕 솔로몬을 보기 위해 땅의 끝 나라 여왕이 온갖 보물을 들고 솔로몬을 찾아왔다.
- 먼 나라에서 온 선지자가 메시지를 선포하자 니느웨는 회개하였다.
- 지금 여기에 솔로몬보다 더욱 지혜롭고, 요나보다 더 강력한 메시지를 선포하는 예수님이 계신다.
- 하지만 이 세대는 예수님을 알아보지 못하고 솔로몬이나 요나보다 못한 취급을 한다.
- 이에 예수님은 이들이 정죄받을 것을 말씀하신다.

- 빛이 세상에 임했으나, 그들은 눈이 멀어 빛을 알아보지 못한다.
- 하나님의 진리의 말씀이 선포되지만, 이 세대는 영적인 눈이 멀어 깨닫지 못한다.
- 예수님을 이것을 지적하신다.

- 우리에게 진리의 빛이 있다면 그 빛은 등경 위에 두어야 한다.
- 그리하여 모든 사람이 우리를 통해 그 빛을 보고 하나님께 영광을 올려드리게 해야한다.

- 자기 집으로 초대한 바리새인의 외식을 지적하신다.
- 바리새인은 외적으로 드러나는 정결예식에는 최선을 다했으나,
- 마음은 정결하지 못했다.
- 하나님께서 원하시는 정결예식은 마음의 정결이었다.

8.인간 찾기(해석)
- 바리새인이 예수님을 자기 집으로 청했으나,
- 선의가 아니라 악의로 청한 것으로 보인다.
- 예수님이 식전에 손을 씻지 않자 비난의 마음을 갖았다. 
- 예수님은 바리새인에게 겉이 아니라 속이 정결해야 한다고 꾸짖으셨다.

- 바리새인의 속에는 탐욕과 악독이 가득했다.
- 권력과 부, 명예욕에 취했던 것이다.

9.적용(나) 
- 진리의 말씀을 마음에 품고, 예수님의 빛을 이웃에게 반사하는 삶을 살아야겠다.
- 예수님의 빛이 내게 없으면 내 몸과 영은 죽은 것이다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-06-26', '누가복음', '11장 41~54절', '위선을 책망하시는 예수님', '[눅11:41-54]
41 그러나 그 안에 있는 것으로 구제하라 그리하면 모든 것이 너희에게 깨끗하리라
42 화 있을진저 너희 바리새인이여 너희가 박하와 운향과 모든 채소의 십일조는 드리되 공의와 하나님께 대한 사랑은 버리는도다 그러나 이것도 행하고 저것도 버리지 말아야 할지니라
43 화 있을진저 너희 바리새인이여 너희가 회당의 높은 자리와 시장에서 문안 받는 것을 기뻐하는도다
44 화 있을진저 너희여 너희는 평토장한 무덤 같아서 그 위를 밟는 사람이 알지 못하느니라
45 한 율법교사가 예수께 대답하여 이르되 선생님 이렇게 말씀하시니 우리까지 모욕하심이니이다
46 이르시되 화 있을진저 또 너희 율법교사여 지기 어려운 짐을 사람에게 지우고 너희는 한 손가락도 이 짐에 대지 않는도다
47 화 있을진저 너희는 선지자들의 무덤을 만드는도다 그들을 죽인 자도 너희 조상들이로다
48 이와 같이 그들은 죽이고 너희는 무덤을 만드니 너희가 너희 조상의 행한 일에 증인이 되어 옳게 여기는도다
49 그러므로 하나님의 지혜가 일렀으되 내가 선지자와 사도들을 그들에게 보내리니 그 중에서 더러는 죽이며 또 박해하리라 하였느니라
50 창세 이후로 흘린 모든 선지자의 피를 이 세대가 담당하되
51 곧 아벨의 피로부터 제단과 성전 사이에서 죽임을 당한 사가랴의 피까지 하리라 내가 너희에게 이르노니 과연 이 세대가 담당하리라
52 화 있을진저 너희 율법교사여 너희가 지식의 열쇠를 가져가서 너희도 들어가지 않고 또 들어가고자 하는 자도 막았느니라 하시니라
53 거기서 나오실 때에 서기관과 바리새인들이 거세게 달려들어 여러 가지 일을 따져 묻고
54 그 입에서 나오는 말을 책잡고자 하여 노리고 있더라

