- 선지자(47,49,50절)
- 무덤(44,47,48절)
- 피(50,51절)

4. 주제만들기: 위선을 책망하시는 예수님

5. 하나님 찾기 (관찰)
- 바리새인과 율법학자의 외식과 위선을 책망하시는 예수님

6. 인간 찾기 (관찰)
- 박하와 운향과 모든 채소의 십일조는 드리되 공의와 하나님께 대한 사랑은 버림
- 회당의 높은 자리와 시장에서 문안 받는 것을 기뻐함
- 평토장한 무덤 같아서 그 위를 밟는 사람이 알지 못함
- 어려운 짐을 사람에게 지우고 한 손가락도 짐에 대지 않음
- 선지자들의 무덤을 만듦

7. 하나님 찾기 (해석) 
- 하나님은 우리의 종교적 행위로 기쁨을 얻으시는 분이 아니시다. 하나님은 우리 마음의 중심을 보시고 하나님을 사랑하고 이웃을 사랑하는 모습이 삶에서 이루어지길 원하신다. 
- 가장 두렵고 떨리는 일은 지식의 열쇠를 갖고 있음에도 들어가지 않고 들어가고자 하는 이도 막는 것이다. 그 일을 내가 하고 있을 수도 있으니 얼마나 떨리는 일인가?
- 하나님은 공의롭고 정의로운 분이시므로 우리에게 주어지는 책임을 판단하신다. 
- 그러므로 우리에게 필요한 것은 겸손함이다. 
- 사역이 잘 된다고 해서, 교회가 부흥한다고 해서, 일이 잘된다고 해서 교만해서는 안 된다. 
- 하나님께 간절히 위선과 외식하는 행동을 하지 않도록 기도해야한다.

8. 인간(해석):
- 인간은 교만한 존재로, 자신의 행위가 어떠한지 객관적인 판단을 하기 어렵다. 
- 바리새인과 율법학자들은 자신의 위치와 추종하는 세력 등으로 인해 큰 권력을 가졌을 것이다. 주어진 힘이 많으니 얼마나 교만했을까?
- 예수님의 책망에 바리새인과 율법학자들은 따져 물으려 거세게 달려들었다. 
- 자신의 잘못을 들었을 때 돌이키거나 뉘우칠 수 있음에도 바리새인과 율법학자들은 그렇지 못했다.
- 이 얼마나 안타까운 일인가? 영적으로 무뎌져 있어도 한참 무뎌져 있는 것이다. 
- 이 시대를 살아가는 우리도 마찬가지다. 
- 진리가 무엇인지? 옳고 그름이 무엇인지? 제대로 판단하지 못하는 경우가 너무 많다.
- 신앙을 갖는 것도 중요하지만 신앙을 바르게 유지하고 지키는 일도 매우 중요하다.

9. 적용(나): 
- 하나님을 바르게 믿고 따를 수 있는 건강한 믿음을 갖도록 기도해야겠다.
- 마음의 중심이 하나님께 향하도록 노력해야겠다.

10. 영적터치(단어/구절)
- 지식의 열쇠를 가져가서 너희도 들어가지 않고 또 들어가고자 하는 자도 막았느니라

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-06-27', '누가복음', '12장 1~10절', '&nbsp;', '(누가복음 12장)
1.  그 동안에 무리 수만 명이 모여 서로 밟힐 만큼 되었더니 예수께서 먼저 제자들에게 말씀하여 이르시되 바리새인들의 누룩 곧 외식을 주의하라
2. 감추인 것이 드러나지 않을 것이 없고 숨긴 것이 알려지지 않을 것이 없나니
3. 이러므로 너희가 어두운 데서 말한 모든 것이 광명한 데서 들리고 너희가 골방에서 귀에 대고 말한 것이 지붕 위에서 전파되리라
4. 내가 내 친구 너희에게 말하노니 몸을 죽이고 그 후에는 능히 더 못하는 자들을 두려워하지 말라
5. 마땅히 두려워할 자를 내가 너희에게 보이리니 곧 죽인 후에 또한 지옥에 던져 넣는 권세 있는 그를 두려워하라 내가 참으로 너희에게 이르노니 그를 두려워하라
6. 참새 다섯 마리가 두 앗사리온에 팔리는 것이 아니냐 그러나 하나님 앞에는 그 하나도 잊어버리시는 바 되지 아니하는도다
7. 너희에게는 심지어 머리털까지도 다 세신 바 되었나니 두려워하지 말라 너희는 많은 참새보다 더 귀하니라
8. 내가 또한 너희에게 말하노니 누구든지 사람 앞에서 나를 시인하면 인자도 하나님의 사자들 앞에서 그를 시인할 것이요
9. 사람 앞에서 나를 부인하는 자는 하나님의 사자들 앞에서 부인을 당하리라
10. 누구든지 말로 인자를 거역하면 사하심을 받으려니와 성령을 모독하는 자는 사하심을 받지 못하리라

