3.반복단어 찾기(형광펜 사용 추천)
누룩/외식: 1절
두려워하지 말라: 4절 7절
두려워할 자/ 두려워하라: 5절 
시인: 8절(2)
부인: 9절(2)

4.주제 만들기: 
두려워할 대상과 말아야 할 대상.

5.하나님 찾기 (관찰)
바리새인의 외식을 경계하도록 가르치시는 예수.
두려워할 것과 두려워 하지말아야 될 존재를 가르치시는 예수.

6.인간 찾기(관찰)
예수의 가르침을 듣는 제자와 무리들.

7.하나님 찾기(해석)
예수님은 두려워할 것과 두려워하지 말 것을 분명하게 가르쳐 주셨다. 

먼저 두려워하지 말 것은 세상의 기득권 세력자들이다. 그들은 믿는 신자를 괴롭히고 때로는 육체의 생명까지도 빼앗을 수 있다. 

하지만 영생까지는 건들 수는 없다. 믿음을 끝까지 지킨 자들은 죽은 후 하나님 사자 앞에 섰을 때 예수님께서 시인해 주신다고 하셨지. 반면에 세상의 권세자를 두려워하여 예수를 배신하면 훗날 하나님 사자 앞에 있을 때 예수님도 그를 시인하지 않으신다 하셨다. 

이런 내용을 보면 신앙 생활한다는 것은 목숨 걸고 해야 한다는 것을 깨우치게 된다. 

그런데도 주님은 자녀의 머리털까지 세실 정도로 전능하셔서 이 세상에서도 능히 우리를 도울 수 있는 분이시다. 

조용히 골방에서도 우리의 신음의 기도 소리 하나하나도 다 드러나사 응답하시는 신실하신 주님이 계셔서 너무 마음의 평안을 누릴 수 있다.

8. 인간 찾기(해석)

9.적용(나):
세상보다 오직 주님을 두려워하는 마음을 가지고 살아야겠다.
그리고 바리새인 같은 외식하는자가 아닌 복음의 본질을 붙잡고 사는 종이 되도록 힘써야겠다.

10. 영적터치 (단어 또는 구절)
1절: 외식을 주의하라?

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

