영혼: 19절(2) 20절
한 부자/어리석은 자: 16절 17절 18절 19절 20절
 유산을 나눔: 13절 14절
물리치라/넉넉한 데있지 아니하니라: 15절

4.주제 만들기: 
어리석은 부자.

5.하나님 찾기 (관찰)
탐심을 물리치라 말씀하시는 예수.
어리석은 한 부자로 비유하시는 예수.

6.인간 찾기(관찰)
형과의  유산문제로 갈등을 놓고 예수님께 도움을 요청하는 한 사람.

7.하나님 찾기(해석)
예수님은 ''탐심''을 피하라고 가르치고 계신다. 비유로 한 어리석은 부자로 예를 드셨다. 

그 어리석은 부자는 자신의 창고에 소유물이 가득 찬 것을 두고 기뻐하며 만족해하였다. 

하지만 예수님께서는 그날 밤에 그 부자가 생명을 잃는다면 그 창고에 재물은 누구 소유가 될 것인가를 지적하셨다. 

사람 대부분은 이 단순한 진리를 알면서도 잊고 사는 경우를 쉽게 본다. 이러한 단순한 사실을 늘 삶 가운데 인지한다면 많은 사람의 삶의 질이 더욱 높아질 것으로 생각된다. 

그렇다고 신자는 반드시 가난해야 생명(구원)을 얻거나 만족감을 얻는다고 여겨지지는 않는다. 

다만 참다운 마음의 평안함이나 만족감은 물질이나 재산이 아닌 오직 주님 안에 거할 때만 가능하다는 진리를 예수님은 가르치고 계신다. 

8. 인간 찾기(해석)

9.적용(나):
진정한 나의 모든 물질의 소유자 되신 예수를 더욱 인식하고 바라봐야겠다.

10. 영적터치 (단어 또는 구절)
20절: 어리석은 자여

