4.주제 만들기: 하나님 나라를 소망하며 깨어 기다리라

5.하나님 찾기(관찰)
- 예수님께서 하나님의 나라를 구하라 말씀하심
- 무서와 말라 아버지께서는 하나님 나라 주시기를 기뻐하신다
- 소유를 팔아 구제하라
- 허리에 띠를 띠고 등불을 켜고 서 있으라

6.인간 찾기(관찰)

7.하나님 찾기(해석)
- 필요한 것을 구하지 말고 아버지의 나라를 구하라 말씀하셨다.
- 이 말씀은 필요한 것이 필요 없다는 것이 아니라, 
- 하나님 나라를 구하면 하나님 아버지께서 자녀에게 필요한 것도 채우신다는 것이다.
- 자녀가 부모와 함께 하는 삶을 바라고 만족해야지, 그렇지 않고 떠나 있으면서 부모의 보살핌을 바라는 것은 상식에 어긋난다.

- 이어서 소유를 팔아 구제하라고 말씀하신다.
- 소유물에 집착하는 것은 하나님께 나아가는 것을 방해하는 장애물이다.
- 소유를 팔아 구제하면, 그것이 구제로 끝나는 것이 아니라,
- 하늘에 둔 보물이 된다고 말씀하신다.

- 구제도 좋지만, 나아가 이 구제를 하나님 나라에 보물을 쌓는 것, 즉 소유보다 하나님 나라를 소망하는 태도와 행위로서 말씀하신 것이다.
- 소유에 집착하는 것은 하나님의 자녀에게 합당하지 않은 마음이다.

- 그리고 항상 깨어 준비하고 있으라 말씀하신다.
- 성도는 하나님 나라를 소망하는 태도를 유지해야 한다. 
- 자신의 소유로 구제하는 삶을 계속하면, 
- 하나님 나라를 소망하는 마음을 유지하기에 좋을 것이다.

8.인간 찾기(해석)

9.적용(나) 
- 내가 좋아하는 것들을 바랄 것인가,
- 아니면 하나님 나라를 바랄 것인가의 고민과 마음가짐은.
- 한 번의 예배, 간헐적인 찬송, 찰나의 은혜 받은 순간에 국한되어서는 안 된다.
- 나는 지금 하나님 나라를 소망하며, 나가 좋아하는 것으로 구제하고 있는가?
- 그것이 계속될 가능성은 얼마나 되는가?

