6. 인간 찾기 (관찰)

7. 하나님 찾기 (해석) 
- 오늘 말씀은 누가복음 11장 9절의 말씀과 상충 된다. 예수님은 11장 말씀에선 구하라고 하셨고, 12장 말씀에선 구하지 말고, 염려도 하지 말라고 하셨다.
- 두 말씀은 어떤 차이가 있을까? 두가지 차이를 생각해 보았다. 염려와 믿음이다. 
- 염려는 인간인 우리가 하는 것이다. 하나님 입장에선 염려가 없다. 그렇다면 염려는 어떨 때 생기는 것일까? 우리가 힘든 일이 생겼거나, 어려움 가운데 있을 때 염려를 하게 된다. 
- 믿음은 인간인 우리가 하나님을 전적은 신뢰하는 마음이다. 믿음이 온전하다면 염려는 없을 것이다. 만약 염려가 생기더라도, 믿음으로 염려를 누룰 것이다. 
- 예수님은 하나님께서 우리의 모든 상황을 알고 계신다고 하셨다. 하나님께서 알고 계시다면 우리는 기도하지 않아도 되는 것일까? 그렇지 않다. 하나님은 우리의 마음의 중심, 믿음을 보시고 원하신다.
- 우리가 구할 때의 기도는 믿음으로부터 시작되어야 한다. 하나님을 전적으로 신뢰하는 믿음에서의 기도는 염려 가운데 있는 기도의 내용과 다를 것이다.
- 염려로 시작되는 기도는 나의 욕구를 충복하기 위함이다. 그것은 믿음이 없이 세상에서의 필요를 채우는 어리석은 요구이다. 
- 예수님께선 이러한 차이를 깨닫게 하시려 우리에게 말씀해주셨다. 이것을 깨우칠 수 있는 믿음이 우리에게 있길 소망한다.

8. 인간(해석):
- 인간은 언제라도 탐욕에 빠질 수 있다. 그로 인해 염려가 생기게 되고, 염려는 자신의 이익을 충족하기 위해 기도라는 수단을 사용하게 만든다. 
- 사탄은 이것을 이용한다. 우리의 욕구가 채워지지 않는 기도는 결국 불신을 갖게 되고, 하나님을 믿는 믿음에서 멀어지게 만든다. 
- 하나님은 우리의 필요를 아신다. 그 분을 신뢰하는 믿음이 우리에게 필요하다.

9. 적용(나): 
- 나의 욕구를 채우기 위한 기도를 한 것을 회개하고, 하나님을 믿는 믿음의 기도를 드리길 소망한다.

10. 영적터치(단어/구절)
- 너희는 무엇을 먹을까 무엇을 마실까 하여 구하지 말며 근심하지도 말라

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

