2025년 7월02일 
누가복음 12장41절~50절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
지혜 있는 진실한 청지기/종: 42절 43절(2)
어리석은 종:45절 47절 48절(2)
많이 요구할 것/많이 달라 할 것: 48절
맞을: 47절 48절

4.주제 만들기: 
진실한 종과 어리석은 종들.

5.하나님 찾기 (관찰)
제자들에게 좋은 종과 어리석은 종에 대하여 비유로 말씀하시는 예수.

6.인간 찾기(관찰)
진실된 청지기: 종을 잘 돌보고 충성을 다하는 종.
어리석은 종들: 주인의 뜻이 아닌 자신의 욕구대로 행하는 불성실한 종들.

7.하나님 찾기(해석)

8. 인간 찾기(해석)
예수님은 자녀들이 진실한 청지기가 되기를 원하신다. 

좋은 청지기가 되는 조건은 주인이 맡겨놓은 종들을 잘 건사하는 것이라 보인다. 

때에 맞추어 양식도 공급해야 한다. 반면에 주인이 되신 주님께 맞을 정도로 잘못된 청지기도 있음을 알려주신다. 

두 종류로 설명하셨는데 첫 번째는 주인의 뜻을 알고도 그대로 행하지 않는 사람이고, 두 번째 부류는 모르고 행하지 않는 사람이다. 

주님은 두 부류를 크게 책망하셨는데 첫 번째 부류를 더욱더 나무라셨다. 이런 거를 생각해보면 주님의 뜻을 아는 사람들은 그만큼 지켜야 할 책임이 크다고 생각이 된다. 

또한 은사를 많이 받은 사람은 주님께서 그만큼 많은 열매를 요청하신다. 그럼 어리석은 청지기는 주인의 뜻을 알고도 행하지 않은 삶을 살았을까? 

처음부터 잘못된 삶을 살지는 않았을 것이다. 돌아오기로 한 주인이 늦어지니 자신의 본분을 망각했을 것이다. 그러면 진실한 청지기로써 사는 비결은 무엇일까? 

아마도 그것은 평상시 주인을 존경하고 사랑하는 마음이 가득 차 있지 않았을까 생각한다. 사랑하는 마음의 크기만큼 순종하고 인내할 것 같다. 

9.적용(나):
주님께 칭찬받는 진실된 청지기가 되도록 삶 가운데 더욱 힘써야겠다.

10. 영적터치 (단어 또는 구절)
42절: 지혜 있고 진실한 청지기가 되어

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

