6.인간 찾기(관찰)

7.하나님 찾기(해석)
- 예수님을 믿는 자와 믿지 않는 자가 분쟁할 것을 말씀하심
- 예수님으로 인한 하나님과 사람 사이의 화해는 화평하고 아름다운 일이지만,
- 복음을 받아들이지 않는 사람들의 저항은 거셀 것이기에,
- 예수님을 믿는 자와 믿지 않는 자의 갈등을 심각할 것을 말씀하신 것 

- 하나님 나라가 임했으나 깨닫지 못하는 자들을 꾸짖으심
- 기상을 맞추는 데는 똑똑하지만, 하나님 나라에 속하는 데는 둔한 자들을 책망하신 것

- 더 큰 일을 당하기 전에 화해하기를 힘쓰라 말씀하시는 예수님
- 예수님은 죄를 짓고도 끝까지 죄 없다 생각하는 자들에게 일침을 가하신다.
- 그들은 동전 한 잎만큼의 죄까지도 갚지 않는다면, 감옥에서 나오지 못하는 존재들이다.
- 그들은 이것을 깨달아야만 한다.
- 모든 사람은 예수님 없이는 구원받을 수 없다.

8.인간 찾기(해석)

9.적용(나) 
- 세상에는 똑똑한 사람들이 많다.
- 자신이 쌓아온 가치관과 세계관을 굳게 믿고 있는 사람들도 많고,
- 그런 사람들이 하는 말을 듣고 그 말에 순응하는 사람들도 많다.
- 그들에게 복음을 전하는 것은 쉬운 일이지만, 그들이 받아들이게 하는 것은 정말 어려운 일이다.
- 한때는 내가 잘하면 되는 줄 알았다.
- 내가 섬기고 화평케 하고 납작 엎드리면 그들이 복음을 받아들일 줄 알았다.
- 그러나 아니었다.
- 주 예수 그리스도께서 역사하지 않으시면, 성령님께서 강력하게 역사하지 않으시면, 그런 일은 일어나지 않는다.
- 나는 그저 겸손한 마음으로 복음을 전할 뿐이다.
- 거두시는 이는 주 예수 그리스도시다. 

