- 불의의 죽음을 당한 사람들이 죄로 인해 죽었다고 생각하는 사람들

7. 하나님 찾기 (해석) 
- 예수님은 잘못 된 신앙관을 갖고 있는 유대인들에게 말씀하셨다. 불의의 사고로 죽은 자가 그 누구보다 죄가 많아서 죽은 것이 아니다. 그러나 회개하지 않으면 멸망할 것이다. 이 말씀은 회개하지 않으면 불의의 죽음을 당한다는 것이 아니다. 
- 하늘나라에서의 멸망을 말씀하셨다. 예수님은 무화과나무의 비유를 통해 이 땅에 오신 목적을 말씀하셨다.
- 포도원지기로 이 땅에 오신 예수님은 열매 맺지 못한 나무를 베어버리려는 하나님의 말씀에 1년만 더 두어달라고 요청하셨다. 
- 예수님은 우리의 멸망을 원하지 않으셨다. 한 영혼이라도 더 구원하시고자 일년을 벌어 회개할 기회를 주셨다. 
- 예수님의 희생으로 열매를 맺어 우리들에게까지 복음이 전해졌다. 
- 값없이 주어진 은혜이지만 내게 복음이 전달되기까지 얼마나 많은 희생이 있었을까?  

8. 인간(해석):
- 하나님을 제대로 알지 못했을 때, 사람이 잘 되고 못 됨을 죄로 판단했었다. 하나님을 잘 믿으면 무조건 성공하는지 알았다. 절 때 그렇지 않다. 
- 하나님은 우리의 성공보다 하나님의 사랑을 제대로 알고 그 분과 동행하는 것을 더 중요하게 생각하신다. 그 분의 관점에선 이 세상에서의 성공을 하나도 중요하지 않다.
- 우리는 하나님을 제대로 알고 제대로 믿기만 하면 된다.

9. 적용(나): 
- 예수님의 사랑을 생각하며 그 사랑에 감사하며 예수님의 사랑에 보답하는 삶을 살아가야겠다. 

10. 영적터치(단어/구절)
- 금년에도 그대로 두소서

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-07-04', '누가복음', '13장 11~20절', '&nbsp;', '(누가복음 13장)
11. 열여덟 해 동안이나 귀신 들려 앓으며 꼬부라져 조금도 펴지 못하는 한 여자가 있더라
12. 예수께서 보시고 불러 이르시되 여자여 네가 네 병에서 놓였다 하시고
13. 안수하시니 여자가 곧 펴고 하나님께 영광을 돌리는지라
14. 회당장이 예수께서 안식일에 병 고치시는 것을 분 내어 무리에게 이르되 일할 날이 엿새가 있으니 그 동안에 와서 고침을 받을 것이요 안식일에는 하지 말 것이니라 하거늘
15. 주께서 대답하여 이르시되 외식하는 자들아 너희가 각각 안식일에 자기의 소나 나귀를 외양간에서 풀어내어 이끌고 가서 물을 먹이지 아니하느냐
16. 그러면 열여덟 해 동안 사탄에게 매인 바 된 이 아브라함의 딸을 안식일에 이 매임에서 푸는 것이 합당하지 아니하냐
17. 예수께서 이 말씀을 하시매 모든 반대하는 자들은 부끄러워하고 온 무리는 그가 하시는 모든 영광스러운 일을 기뻐하니라
18.  그러므로 예수께서 이르시되 하나님의 나라가 무엇과 같을까 내가 무엇으로 비교할까
19. 마치 사람이 자기 채소밭에 갖다 심은 겨자씨 한 알 같으니 자라 나무가 되어 공중의 새들이 그 가지에 깃들였느니라
20. 또 이르시되 내가 하나님의 나라를 무엇으로 비교할까

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
