1:감동받는 단어나 구절 찾기(영적터치)

2025년 7월05일 
누가복음 13장11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
귀신 들려 앓으며 꼬부라져 펴지 못하는 여자: 11절 12절 13절
회당장: 14절 15절
예수: 12절 14절 15절 17절 18절
안식일: 14절(2) 15절 16절
병에서 놓였다/고침을 받을 것이요: 12절 14절
하나님의 나라: 18절 20절
비교 할까: 18절 20절

4.주제 만들기: 
안식일에 꼬부라진 여자를 고치신 예수.

5.하나님 찾기 (관찰)
치료자  예수.
외식자 회당장을 책망하시는 예수.
하나님 나라를 비유로 말씀하시는 예수.

6.인간 찾기(관찰)
안식일에 병고친 예수를 향하여 분을 내는 회당장.

7.하나님 찾기(해석)
예수님은 회당에서 안식일에 가르치실 때 18년 동안 귀신으로 인하여 허리가 굽은 여인을 고쳐주셨다. 

그 여인은 곧장 주님께 다가와 감사와 하나님께 영광을 올렸다. 

반면 한 사람 회당장은 분노가 가득 차서 예수님께 항의하였다. 율법을 어기면서 이러한 일을 하였는가였다. 그러한 회당 장의 잘못된 마음을 아시고 "외식하는 자들이여"라고 책망하셨다.

 예수님은 인칭을 단수로 사용하지 않고 복수로 사용하셨다. 

왜 그렇게 하셨을까? 아마도 예수님은 그 회당장 뿐만 아니라 현대에 살고 있는 영적 지도자들까지 포함하여 교훈하신 듯하다고 생각해본다. 

8. 인간 찾기(해석)
회당장 처럼 외식하는 마음을 어떻게 생기는 것일까? 

간단하게 생각하면 영혼을 사랑하고 소중히 여기는 마음보다 자신을 높이거나 지켜줄 율법을 귀하게 생각하는 것 같다. 

즉 외식은 스스로 높아지고자 하는 근본에서 발생할 수 있다고 생각해본다. 

회당장은 율법을 잘 가르칠지는 모르지만 정작 말씀을 만드신 하나님의 근본적 정인인 ''영혼 사랑"에 대해 영적으로 무지한 사람으로 느껴진다. 

복음의 본질을 벗어나 힘을 잃어가고 있는 현대의 많은 교회를 보는 듯하여 안타까움과 종으로써 큰 책임을 느낀다.

9.적용(나):
혹시 나도 회당장의 율법주의 처럼 혹은 외식하는 부분은 없는지 살펴야겠다. 뿐만아니라 영혼들을 진심으로 사랑하며 섬기는지 더욱 성찰해야 겠다. 

주변에 고통가운데 있는 사람이 있다면 시간을 내어 섬겨야겠다.

10. 영적터치 (단어 또는 구절)
15절: 외식하는 자들야

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-07-05', '누가복음', '13장 21~30절', '&nbsp;', '(누가복음 13장)
21. 마치 여자가 가루 서 말 속에 갖다 넣어 전부 부풀게 한 누룩과 같으니라 하셨더라
22.  예수께서 각 성 각 마을로 다니사 가르치시며 예루살렘으로 여행하시더니
23. 어떤 사람이 여짜오되 주여 구원을 받는 자가 적으니이까 그들에게 이르시되
24. 좁은 문으로 들어가기를 힘쓰라 내가 너희에게 이르노니 들어가기를 구하여도 못하는 자가 많으리라
25. 집 주인이 일어나 문을 한 번 닫은 후에 너희가 밖에 서서 문을 두드리며 주여 열어 주소서 하면 그가 대답하여 이르되 나는 너희가 어디에서 온 자인지 알지 못하노라 하리니
26. 그 때에 너희가 말하되 우리는 주 앞에서 먹고 마셨으며 주는 또한 우리를 길거리에서 가르치셨나이다 하나
27. 그가 너희에게 말하여 이르되 나는 너희가 어디에서 왔는지 알지 못하노라 행악하는 모든 자들아 나를 떠나 가라 하리라
28. 너희가 아브라함과 이삭과 야곱과 모든 선지자는 하나님 나라에 있고 오직 너희는 밖에 쫓겨난 것을 볼 때에 거기서 슬피 울며 이를 갈리라
29. 사람들이 동서남북으로부터 와서 하나님의 나라 잔치에 참여하리니
30. 보라 나중 된 자로서 먼저 될 자도 있고 먼저 된 자로서 나중 될 자도 있느니라 하시더라

