2025년 7월06일 
누가복음 13장21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
구원/들어가기: 23절 24절(2)
너희가 어디에서 온 자인지 알지 못하노라: 25절 27절
좁은 문: 24절 25절 
예수/집주인: 22절 25절 26절 27절 
나중 된 자: 30절(2)
먼저 될 자/먼저 된 자: 30절(2)

4.주제 만들기: 
구원의 조건

5.하나님 찾기 (관찰)
마을로 다니며 가르치시는 예수.
구원받기 위해서는 좁은 문으로 들어가기를 힘쓰라 말씀 하시는 예수.

6.인간 찾기(관찰)
구원에 대하여 묻는 사람.
나중 된 자가 먼저 되고, 먼저 된자로서 나중 될 자.

7.하나님 찾기(해석)
예수님은 구원받기 위해서는 좁은 문으로 들어가기를 힘쓰라고 말씀하셨다. 

그 좁은 구원의 문은 평상시에는 누구에게나 활짝 열려있으나 때가 돼서 한번 닫히면 다시는 열리지 않는다는 내용이다. 

그때 구원받지 못한 어떤 사람은 평상시에 주님과 식사 교제하고 길에서 가르침을 받은 것을 내세우며 자신의 억울함을 하소연한다. 

그러나 예수님은 단호하셨다. 그는 구원의 조건으로 내세웠지만 예수님은 받아주지 않으셨다. 그러면 구원의 조건은 무엇일까? 

평상시 성경 공부하고 성도들과 은혜를 나누고 친교 하는 것만으로는 구원의 조건을 충족시킬 수 없다는 내용이다. 

모든 신자가 알듯이 구원의 조건은 주님을 자신의 구원자로 즉 주인으로 받아들이고 마음에 모셔야 가능하다. 

결국 예수님은 구원의 조건은 자신을 아는 것이 아닌 예수님을 믿고 따르는 자들을 인정하신다는 것이다. 

믿는 자들의 열매로는 그들은 예수님이 걸으셨던 고난의 길 인 좁은 문으로 들어가기 위해 힘쓰는 태도가 동반되는 것 같다.

8. 인간 찾기(해석)

9.적용(나):
주님을 믿음으로 늘 구원의 확신의 기쁨으로 살며, 좁은 문으로 들어가기를 힘써야겠다.

10. 영적터치 (단어 또는 구절)
24절: 좁은 문으로 들어가기를 힘쓰라.

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-07-06', '누가복음', '13장 31~35절', '핍박에도 완성되는 구속 사역', '[눅13:31-35]
31 곧 그 때에 어떤 바리새인들이 나아와서 이르되 나가서 여기를 떠나소서 헤롯이 당신을 죽이고자 하나이다
32 이르시되 너희는 가서 저 여우에게 이르되 오늘과 내일은 내가 귀신을 쫓아내며 병을 고치다가 제삼일에는 완전하여지리라 하라
33 그러나 오늘과 내일과 모레는 내가 갈 길을 가야 하리니 선지자가 예루살렘 밖에서는 죽는 법이 없느니라
34 예루살렘아 예루살렘아 선지자들을 죽이고 네게 파송된 자들을 돌로 치는 자여 암탉이 제 새끼를 날개 아래에 모음 같이 내가 너희의 자녀를 모으려 한 일이 몇 번이냐 그러나 너희가 원하지 아니하였도다
35 보라 너희 집이 황폐하여 버린 바 되리라 내가 너희에게 이르노니 너희가 주의 이름으로 오시는 이를 찬송하리로다 할 때까지는 나를 보지 못하리라 하시니라

