1. 1분기도

2. 본문성경 읽기(3번)

3. 반복단어 찾기(형광펜 추천)
- 선지자(33.34절)

4. 주제만들기: 핍박에도 완성되는 구속 사역

5. 하나님 찾기 (관찰)
- 이 곳을 떠나라며 협박하는 바리새인에게 자신의 갈 길을 가겠다 말하시는 예수님
- 예루살렘이 황폐해질 것을 말씀하시는 예수님

6. 인간 찾기 (관찰)
- 헤롯을 핑계로 예수님을 쫓아내는 바리새인

7. 하나님 찾기 (해석) 
- 죽음이라는 두려움으로 예수님을 쫓아내고자 했던 바리새인에게 예수님은 오히려 담대히 자신의 행할 일을 다하겠다고 말씀하셨다. 
- 예수님 십자가를 지기 전까지 귀신 들린자들과 병 들린자를 고치겠다고 말씀하셨다. 예수님은 연약하고, 고난 가운데 있는 자들을 조금이라도 더 만나서 그들을 고치고 소망을 주시고자 하셨다.
- 주의 일을 할 때 예수님과 같은 마음이 내 안에 있길 소망한다. 단, 한 사람이라도 더 예수님을 알 수 있도록 한 영혼을 귀하게 생각하는 마음이 우리에게 있어야 한다.

8. 인간(해석):
- 바리새인은 여전히 예수님을 쫓아내고자 했다. 강팍한 마음은 우리가 어찌할 수 없다. 하나님의 은혜가 주어져야 한다. 하나님을 알고 예수님의 십자가를 아는 것이 얼마나 큰 은혜인지 다시 생각해본다.

9. 적용(나): 
- 한 영혼을 귀하게 여기는 마음이 내 안에 가득 임하길
- 십자가의 은혜에 감사하며 기도해야겠다.

10. 영적터치(단어/구절)
- 오늘과 내일은 내가 귀신을 쫓아내며 병을 고치다가 제삼일에는 완전하여지리라 하라

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-07-07', '누가복음', '14장 1~10절', '바리새인들 앞에서', '누가복음 14장
1   안식일에 예수께서 한 바리새인 지도자의 집에 떡 잡수시러 들어가시니 그들이 엿보고 있더라
2   주의 앞에 수종병 든 한 사람이 있는지라
3   예수께서 대답하여 율법교사들과 바리새인들에게 이르시되 안식일에 병 고쳐 주는 것이 합당하냐 아니하냐
4   그들이 잠잠하거늘 예수께서 그 사람을 데려다가 고쳐 보내시고
5   또 그들에게 이르시되 너희 중에 누가 그 아들이나 소가 우물에 빠졌으면 안식일에라도 곧 끌어내지 않겠느냐 하시니
6   그들이 이에 대하여 대답하지 못하니라
7   청함을 받은 사람들이 높은 자리 택함을 보시고 그들에게 비유로 말씀하여 이르시되
8   네가 누구에게나 혼인 잔치에 청함을 받았을 때에 높은 자리에 앉지 말라 그렇지 않으면 너보다 더 높은 사람이 청함을 받은 경우에
9   너와 그를 청한 자가 와서 너더러 이 사람에게 자리를 내주라 하리니 그 때에 네가 부끄러워 끝자리로 가게 되리라
10   청함을 받았을 때에 차라리 가서 끝자리에 앉으라 그러면 너를 청한 자가 와서 너더러 벗이여 올라 앉으라 하리니 그 때에야 함께 앉은 모든 사람 앞에서 영광이 있으리라

