높은 자리: 7, 8
끝자리: 9, 10

4.주제 만들기: 바리새인들 앞에서

5.하나님 찾기(관찰)
- 바리새인 지도자의 집에 들어가신 예수님
- 안식일에 수종병든 자를 고치시는 예수님
- 바리새인들을 가르치시는 예수님

6.인간 찾기(관찰)
- 바리새인 지도자와 바리새인들
- 수종병든 자

7.하나님 찾기(해석)
- 바리새인 지도자와 바리새인들이 지켜보는 앞에서 수종병든 자를 고치시는 예수님
- 아마도 예수님 앞에 선 수종병든 자는 바리새인들이 예수님을 시험하고 책 잡고자 데려온 인물일 가능성도 있을 것이다.
- 예수님은 이것을 아시면서도 바리새인들에게 질문을 던지시며,
- 수종병을 고쳐주셨다.
- 그리고 누구나 아들이나 소가 우물에 빠지면 안식일에라도 구하지 않겠느냐? 너희는 그러지 않겠느냐 질문하신다.

- 초대 받은 자들이 높은 자리에 앉는 모습을 보시며,
- 높임 받기를 좋아하는 그들에게 낮은 자리를 찾아가라고 말씀하신다.
- 초대한 사람이 부르기 전에는 높은 자리에 앉지 말라고 하시며,
- 낮은 자리에 앉았으나 초대한 사람이 높은 자리에 부르면 그때 보는 이들에게 높임을 받을 것이라 말씀하신다.
- 이것은 그들의 교만한 태도에 대해 말씀하신 것으로서,
- 스스로 높다 생각하지 말고 남을 나보다 낫게 여기는 마음을 가지라는 말씀으로 해석하는 것이 우리에게 유익할 것이다.
- 나를 높이는 것은 내가 아니라, 남들의 눈과 입이다.

8.인간 찾기(해석)
- 예수님을 시험코자 모인 바리새인들은 예수님의 질문에 대답을 하지 못했다.
- 그들 중에는 자신들의 전통을 어기는 예수님께 화가 나서 이를 가는 자도 있었고,
- 한 두명은 예수님의 말씀에 깨어지고 감동을 받는 자도 있었을 것이다.

- 수종병든 자는 어떤 마음으로 예수님 앞에 섰는지 모르겠으나,
- 병 고침을 받은 이후로 예수님의 능력에 감탄하였을 것이다.
- 다만, 그가 구원받았는지 성경에 쓰여있지 않으나 예수님의 능력을 체험한 그는 아마도 예수님을 구원자로 믿게 되었을 것이다. 

- 인간의 높고 낮음은 스스로 평가하는 것이 아니라, 남들이 평가하는 것이다.
- 예수님께서는 섬기는 자, 낮은 자가 되라고 말씀하셨다.
- 우리는 스스로 겸비하여 마음도 언행도 겸손한 자가 돼야 한다.

9.적용(나) 
- 복음 전파를 비난하는 사람들 앞에서 내가 할 말을 정확히 해야겠다.
- 사람 살리는 행위를 비난하는 사람들 앞에서 내가 할 말을 정확히 해야겠다.
- 성령 하나님께서 할 말을 주실 것이다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-07-08', '누가복음', '14장 11~20절', '&nbsp;', '(누가복음 14장)
11. 무릇 자기를 높이는 자는 낮아지고 자기를 낮추는 자는 높아지리라
12. 또 자기를 청한 자에게 이르시되 네가 점심이나 저녁이나 베풀거든 벗이나 형제나 친척이나 부한 이웃을 청하지 말라 두렵건대 그 사람들이 너를 도로 청하여 네게 갚음이 될까 하노라
13. 잔치를 베풀거든 차라리 가난한 자들과 몸 불편한 자들과 저는 자들과 맹인들을 청하라
14. 그리하면 그들이 갚을 것이 없으므로 네게 복이 되리니 이는 의인들의 부활시에 네가 갚음을 받겠음이라 하시더라
15.  함께 먹는 사람 중의 하나가 이 말을 듣고 이르되 무릇 하나님의 나라에서 떡을 먹는 자는 복되도다 하니
16. 이르시되 어떤 사람이 큰 잔치를 베풀고 많은 사람을 청하였더니
17. 잔치할 시각에 그 청하였던 자들에게 종을 보내어 이르되 오소서 모든 것이 준비되었나이다 하매
18. 다 일치하게 사양하여 한 사람은 이르되 나는 밭을 샀으매 아무래도 나가 보아야 하겠으니 청컨대 나를 양해하도록 하라 하고
19. 또 한 사람은 이르되 나는 소 다섯 겨리를 샀으매 시험하러 가니 청컨대 나를 양해하도록 하라 하고
20. 또 한 사람은 이르되 나는 장가 들었으니 그러므로 가지 못하겠노라 하는지라

