4.주제 만들기: 
죄인을 찾으시는 예수.

5.하나님 찾기 (관찰)
 참 목자의 태도를 비유로 설명하시는 예수.
 수군거리는 바리새인과 서기관들에게 비유로 말씀하시는 예수.
비유(100마리 양중 잃어버린 한마리 양, 잃어버린 드라크마)

6.인간 찾기(관찰)
예수께 말씀을 듣기위하여 다가가는 세리와 죄인들.
예수께 수군거리는 바리새인과 서기관들.

7.하나님 찾기(해석)
예수님은 잃어버린 한 영혼을 찾기 위해 위한 간절한 마음을 가지고 계신다. 

예수님은 때때로 세상의 조롱과 오해를 참으시면서도 죄인들과 대화하며 식사 교제를 기꺼이 하신다. 

예수님이 이렇게 하시는 이유는 한가지인 것 같다. 예수님은 ‘사랑’ 그 자체이시기 때문이다. 

죽기까지 영혼을 사랑하심의 모습을 다시 느낀다. 

나는 혹시 영적으로 이미 구원받은 편안 상대인 동역자들과 식사 교제를 좋아하는 만큼이나 불신자들과의 만남을 갖고 있는가? 반성하게 된다.

8. 인간 찾기(해석)

9.적용(나):
복음전도(마포대교,한강대교)에 더욱 힘써야겠다.

