INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-07-11', '누가복음', '14장 31~35절', '소유를 버리지 아니하면 능히 내 제자가 되지 못하리라', '[눅14:31-35]
31 또 어떤 임금이 다른 임금과 싸우러 갈 때에 먼저 앉아 일만 명으로써 저 이만 명을 거느리고 오는 자를 대적할 수 있을까 헤아리지 아니하겠느냐
32 만일 못할 터이면 그가 아직 멀리 있을 때에 사신을 보내어 화친을 청할지니라
33 이와 같이 너희 중의 누구든지 자기의 모든 소유를 버리지 아니하면 능히 내 제자가 되지 못하리라
34 소금이 좋은 것이나 소금도 만일 그 맛을 잃으면 무엇으로 짜게 하리요
35 땅에도, 거름에도 쓸 데 없어 내버리느니라 들을 귀가 있는 자는 들을지어다 하시니라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

1. 1분기도

2. 본문성경 읽기(3번)

3. 반복단어 찾기(형광펜 추천)
- 임금(31절)
- 소금(34절)

4. 주제만들기: 소유를 버리지 아니하면 능히 내 제자가 되지 못하리라

5. 하나님 찾기 (관찰)
- 임금의 이야기로 비유하시는 예수님
- 자기의 모든 소유를 버리지 않으면 능히 제자가 되지 못하리라 말씀하신 예수님
- 소금으로 비유하신 예수님

6. 인간 찾기 (관찰)

7. 하나님 찾기 (해석) 
- 예수님은 망대, 임금의 비유로 무엇을 준비해야하는지, 무엇이 준비되어야하는지 말씀하시며 제자로 살아가는 길에 영적으로 무장되어야 함을 말씀해주셨다.
- 예수님은 제자로 살아가는 삶과 그렇지 않은 삶에 대해 하늘나라를 말씀하시며 우리에게 도전을 주셨다. 망대를 세우며 과정에서 완전한 계획 수립, 다른 나라와의 화친을 위한 임금의 회유책, 이렇듯 우리가 하늘나라를 소망한다면 제자의 삶을 살아가야 한다.
- 예수님은 소유에 대해서도 말씀하셨다. 소유는 물질의 영역에 주인이 주님임을 인정함과 동시에 내 자신을 부인하는 길이다. 이 과정은 연약한 인간인 우리에게 가장 어려운 길일텐데 명예, 자존심, 나의 꿈, 가족, 관계 등 물질의 영역을 넘어 내가 현재 있는 사회적 위치, 희망 등을 모두 주님께 맡겨야한다는 것이다.

8. 인간(해석):
- 오늘 말씀을 통해 내가 얼마나 연약하고 어리석은 존재인지 다시 깨닫는다. 모든 것을 주님께 맡기고(완전한 순종) 따르면 되는데 아직 내려놓지 못하는 삶을 살아가고 있다. 

9. 적용(나): 
- 하늘나라를 소망하는 삶을 입으로만 고백하는 것이 아닌 행동으로 실천하는 내가 되어야겠다.
- 모든 소유를 주님께 맡기고, 이생의 자랑을 위해 살아가지 않도록 성령님의 도우심을 간구해야겠다.

10. 영적터치(단어/구절)
- 자기의 모든 소유를 버리지 아니하면 능히 내 제자가 되지 못하리라

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-07-12', '누가복음', '15장 11~20절', '&nbsp;', '(누가복음 15장)
11.  또 이르시되 어떤 사람에게 두 아들이 있는데
12. 그 둘째가 아버지에게 말하되 아버지여 재산 중에서 내게 돌아올 분깃을 내게 주소서 하는지라 아버지가 그 살림을 각각 나눠 주었더니
13. 그 후 며칠이 안 되어 둘째 아들이 재물을 다 모아 가지고 먼 나라에 가 거기서 허랑방탕하여 그 재산을 낭비하더니
14. 다 없앤 후 그 나라에 크게 흉년이 들어 그가 비로소 궁핍한지라
15. 가서 그 나라 백성 중 한 사람에게 붙여 사니 그가 그를 들로 보내어 돼지를 치게 하였는데
16. 그가 돼지 먹는 쥐엄 열매로 배를 채우고자 하되 주는 자가 없는지라
17. 이에 스스로 돌이켜 이르되 내 아버지에게는 양식이 풍족한 품꾼이 얼마나 많은가 나는 여기서 주려 죽는구나
18. 내가 일어나 아버지께 가서 이르기를 아버지 내가 하늘과 아버지께 죄를 지었사오니
19. 지금부터는 아버지의 아들이라 일컬음을 감당하지 못하겠나이다 나를 품꾼의 하나로 보소서 하리라 하고
20. 이에 일어나서 아버지께로 돌아가니라 아직도 거리가 먼데 아버지가 그를 보고 측은히 여겨 달려가 목을 안고 입을 맞추니

