2025년 7월19일 
누가복음 17장11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
나병환자(열명): 12절 13절 14절 17절
사마리아(이방인) 나병환자:15절 16절 18절 19절
하나님 나라: 20절(2)
하나님께 영광: 15절 18절
깨끗함을 받음: 14절 17절
예수: 11절 12절 13절 16절 17절 

4.주제 만들기: 
깨끗해진 열명의 나병환자와  구원받은 이방인.

5.하나님 찾기 (관찰)
 예루살렘으로 가시는 예수
나병환자 10명을 고치시는 예수.
그중 하나님께 영광을 올리고 다가와 감사하는 이방인을 구원하시는 예수.

6.인간 찾기(관찰)
예수께 치료를 요청하며 부르짖는 10명의 나병환자.
고침받은후 예수께 엎드려 감사하는 이방인.

7.하나님 찾기(해석)

8. 인간 찾기(해석)
예수님은 자신을 향하여 고침을 바라며 소리치는 나병환자 10명을 고쳐주셨다. 

치료받은 10명 중 한 명만 예수님께 엎드려 감사함을 표현하고 하나님께 영광을 올렸다. 

그 한 사람은 사마라인이고 이방인이었다. 그러면 자연스럽게 9명은 유대인이라고 추측할 수 있다. 

예수님은 나머지 9명은 하나님께 영광을 올리지 않은 것에 관하여 물으셨다. 

치료받은 사마리아인은 육체뿐만 아니라 영혼도 믿음을 통하여 구원받았다. 

반면 나머지 9명은 육체만 치료받았을 확률이 높다. 치료받기 전에 10명의 나병환자 중 사마리아인은 아마도 평소 따돌림을 받았을 것으로 추측이 된다. 

사회적으로 외면당하는 그룹 가운데서도 왕따당하는 처지라면 정말 고립된 외롭고 힘든 환경이지만 그는 예수라는 한 줄기 빛인 예수를 붙잡았다. 

결과적으로 그는 몸을 치료받았을 뿐만 아니라 구원받게 되었다. 주님 구원의 대상으로는 누구든지 믿음을 갖고 주님을 찾는다면 구원을 얻는다는 진리를 다시 만나게 된다.

9. 적용
기도에 응답하시는 주님께 늘 감사하며,특별히 구원의 감동과 기쁨으로 하루하루 만족하며 살아야겠다.

10. 영적터치 (단어 또는 구절)
19절: 일어나 가라 네 믿음이 너를 구원하였느니라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-07-19', '누가복음', '17장 21~30절', '&nbsp;', '(누가복음 17장)
21. 또 여기 있다 저기 있다고도 못하리니 하나님의 나라는 너희 안에 있느니라
22. 또 제자들에게 이르시되 때가 이르리니 너희가 인자의 날 하루를 보고자 하되 보지 못하리라
23. 사람이 너희에게 말하되 보라 저기 있다 보라 여기 있다 하리라 그러나 너희는 가지도 말고 따르지도 말라
24. 번개가 하늘 아래 이쪽에서 번쩍이어 하늘 아래 저쪽까지 비침같이 인자도 자기 날에 그러하리라
25. 그러나 그가 먼저 많은 고난을 받으며 이 세대에게 버린 바 되어야 할지니라
26. 노아의 때에 된 것과 같이 인자의 때에도 그러하리라
27. 노아가 방주에 들어가던 날까지 사람들이 먹고 마시고 장가 들고 시집 가더니 홍수가 나서 그들을 다 멸망시켰으며
28. 또 롯의 때와 같으리니 사람들이 먹고 마시고 사고 팔고 심고 집을 짓더니
29. 롯이 소돔에서 나가던 날에 하늘로부터 불과 유황이 비오듯 하여 그들을 멸망시켰느니라
30. 인자가 나타나는 날에도 이러하리라

