2025년 7월20일 
누가복음 17장21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
인자의 날/자기 날/인자의 때/ 인자가 나타나는 날: 22절 24절 26절 30절
하늘 아래: 24절
먹고 마시고: 27절 28절
멸망시켰으며/멸망시켰느니라: 27절 29절
그러하리라: 24절 26절

4.주제 만들기: 
인자의 날(마지막 때)

5.하나님 찾기 (관찰)
바리새인들에게 하나님 나라에 대하여 답하시는 예수.
제자들에게 마지막 때 일어날 상황을 예견하시는 예수.
(많은 사람들이 세상 일에 빠져 노아와 롯의 시대처럼 구원을 받지못함) 

6.인간 찾기(관찰)
예수님 말씀을 듣는 제자들.
하나님  나라의 때를 묻는 바리새인들.


7.하나님 찾기(해석)
예수님은 마지막 때인 인자의 날에 닥칠 일들을 제자들에게 설명하셨다. 

마지막 날에는 많은 사람이 비참한 마지막을 맞이할 거라 말씀하셨다. 

그날에는 세상의 일에만 몰입하는 자들이 대부분이다. 먹고 마시고 결혼하고 나무를 심고 집을 짓는 일에 열심과 즐거움을 취하다가 제일 중요한 하나님을 잊고 살다가 지옥 불에 떨어지는 끔찍한 미래를 말씀하셨다. 

과거에 있었던 노아 때와 롯의 때를 상기시켰다. 단순하게 육의 관점에서는 생각하면 세상에서 인간의 육체적인 필요와 즐거움을 취하는 것이 큰 문제인가 생각한다면 틀린 생각이다. 

하나님은 인간을 육뿐만 아니라 동물은 없는 영을 주셨고 하나님과 교제하며 특별히 천국 소망을 주셨다. 

그것을 지키기 위해서 인간을 구원하시기 위해 스스로 죽기까지 사랑하셨다. 그 크신 사람을 하루하루 잊고 산다면 번쩍거리는 마지막 날 하루에 슬픈 마지막을 누구나 받는 처지에 놓일 것이라 주님은 경각심을 주고 계신다. 

과거의 실패한 일들을 교훈 삼아 노아처럼 구원의 길로 가기를 주님은 바라고 계심을 본다.

8. 인간 찾기(해석)

9. 적용
오늘이 마지막 인것처럼 깨어 기도하고, 주님의 재림을 늘 갈망하며 기다리는 태도로 살아야겠다.

10. 영적터치 (단어 또는 구절)
30절: 인자가 나타나는 날에도 어러하리라


11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-07-20', '누가복음', '17장 31~37절', '같은 신앙생활, 다른 결과', '[눅17:31-37]
31 그 날에 만일 사람이 지붕 위에 있고 그의 세간이 그 집 안에 있으면 그것을 가지러 내려가지 말 것이요 밭에 있는 자도 그와 같이 뒤로 돌이키지 말 것이니라
32 롯의 처를 기억하라
33 무릇 자기 목숨을 보전하고자 하는 자는 잃을 것이요 잃는 자는 살리리라
34 내가 너희에게 이르노니 그 밤에 둘이 한 자리에 누워 있으매 하나는 데려감을 얻고 하나는 버려둠을 당할 것이요
35 두 여자가 함께 맷돌을 갈고 있으매 하나는 데려감을 얻고 하나는 버려둠을 당할 것이니라
[36] 
37 그들이 대답하여 이르되 주여 어디오니이까 이르시되 주검 있는 곳에는 독수리가 모이느니라 하시니라

