- 잃다(33절)

4. 주제만들기: 같은 신앙생활, 다른 결과

5. 하나님 찾기 (관찰)
- 숨을 보전하고자 하는 자는 잃고 잃는 자는 살리라고 말씀하신 예수님
- 둘이 한 자리에 누워있더라도 한명은 데려감을 얻고, 한명은 버려둠을 당할 것이라 말씀하신 예수님
- 두 여자의 비유로 맷돌을 돌리다 한명은 데려감을 얻고, 한명은 버려둠을 당할 것이라 말씀하신 예수님

6. 인간 찾기 (관찰)

7. 하나님 찾기 (해석) 
- 예수님은 우리의 본질적인 신앙생활에 대해서 말씀하셨다. 둘이 같은 자리에 누워있고, 맷돌을 같이 돌리는 모습은 우리의 신앙생활을 떠올리게 한다. 
- 함께 자고 돌리며 같은 신앙생활을 하지만 한명은 하늘로, 한명은 버려둠으로 다른 결과를 얻게 되는 것을 한탄하셨을 것이다.
- 예수님은 우리의 신앙생활이 진심이길 원하셨다. 그리고 바른 신앙생활을 하길 원하셨다.
- 또한 신앙생활 가운데 돌이키고 싶은 순간들이 있다. 이것은 개개인이 다른 이유로 돌아보고 싶은 유혹을 받게 된다. 
- 그러나 예수님은 돌아보지 말라고 말씀하신다. 우리는 좁은 길을 끊임없이 추구하며 나의 힘을 의지하지 말고 하나님의 능력을 의지해야 한다. 

8. 인간(해석):

9. 적용(나): - 과거의 즐거움을 주었던 일이 떠오를 때 보혈의 능력을 벗어날 수 있도록 기도해야겠다.

10. 영적터치(단어/구절)
- 돌이키지 말 것이니라

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-07-21', '누가복음', '18장 1~10절', '늘 기도하고 낙심하지 말아야 하는 이유&nbsp;', '누가복음 18장
1   예수께서 그들에게 항상 기도하고 낙심하지 말아야 할 것을 비유로 말씀하여
2   이르시되 어떤 도시에 하나님을 두려워하지 않고 사람을 무시하는 한 재판장이 있는데
3   그 도시에 한 과부가 있어 자주 그에게 가서 내 원수에 대한 나의 원한을 풀어 주소서 하되
4   그가 얼마 동안 듣지 아니하다가 후에 속으로 생각하되 내가 하나님을 두려워하지 않고 사람을 무시하나
5   이 과부가 나를 번거롭게 하니 내가 그 원한을 풀어 주리라 그렇지 않으면 늘 와서 나를 괴롭게 하리라 하였느니라
6   주께서 또 이르시되 불의한 재판장이 말한 것을 들으라
7   하물며 하나님께서 그 밤낮 부르짖는 택하신 자들의 원한을 풀어 주지 아니하시겠느냐 그들에게 오래 참으시겠느냐
8   내가 너희에게 이르노니 속히 그 원한을 풀어 주시리라 그러나 인자가 올 때에 세상에서 믿음을 보겠느냐 하시니라
9   또 자기를 의롭다고 믿고 다른 사람을 멸시하는 자들에게 이 비유로 말씀하시되
10   두 사람이 기도하러 성전에 올라가니 하나는 바리새인이요 하나는 세리라

