예수: 5(2)
나귀 새끼: 33(2), 35
겉옷: 35(2)
제자: 37, 39

4.주제 만들기: 찬양받기 합당하신 예수님

5.하나님 찾기(관찰)
- 나귀 새끼를 가져오라 명하시는 예수님
- 나귀 새끼에 타신 예수님
- 바리새인에게 대답하시는 예수님 

6.인간 찾기(관찰)
- 예수님의 명대로 나귀 새끼를 데려오는 제자들
- 제자들에게 나귀 새끼를 주는 나귀 새끼의 주인 
- 자기 겉옷을 나귀의 안장으로 올려놓는 제자들
- 자기 겉옷을 나귀가 가는 길에 펴는 제자들  
- 소리 높여 예수님을 찬양하는 제자들
- 제자들을 책망하라 예수님께 부탁하는 바리새인들

7.하나님 찾기(해석)
- 성경에 적힌대로 나귀 새끼를 가져오라 하신 예수님
- 나귀 새끼를 타고 감란산 내리막길에서 제자들에게 찬양을 받는 예수님
- 제자들이 지금까지 본 바 능한 일로 인하여 감정적으로 흥분하여 찬양을 올렸으나 예수님을 그것을 말리지 않으시고 받으심
- 제자들은 앞으로 일어날 일을 알지 못했고, 
- 제자들은 어쩌면 잘못된 기대를 하고 있을지 모르나,
- 예수님은 그들의 찬양을 옳게 여기셨고,
- 그들은 결과적으로 자신들이 알지 못하는 올바른 찬양과 영광을 하나님께 올려드렸음.

- 제자들을 책망하라는 바리새인들에게 그들이 하지 않으면 돌들이 소리지르리라 말씀하시는 예수님.
- 예수님께서는 제자들의 찬양을 기쁘게 받으신 것. 

8.인간 찾기(해석)
- 자기의 겉옷을 나귀 안장으로 올리고 길에 펴놓음으로, 자신의 소유를 왕되신 예수님께 바치는 행위를 함.
- 제자들은 비록 잠시뿐이지만, 예수님을 왕으로, 자신의 주인으로 모시고자 함.
- 자신들이 본 바 능한 일들로 인해, 감정적으로 감동하여 큰 소리로 예수님을 찬양함.
 
- 바리새인들은 예수님을 주로 믿지 않고 선생으로 여겼기에 제자들의 찬양 소리가 못마땅했음.
- 그래서 예수 선생이여 저들을 책망하소서 라고 말함.
- 바리새인들은 예수님을 왕 또는 주님으로 모실 생각이 없었음.

9.적용(나) 
- 찬양받으시기에 합당하신 예수님.
- 제자들이 단편적이고 잘 알지 못하고 감정적인 찬양을 했으나, 그 찬양은 옳은 것이었다.
- 나도 하나님을 얼마나 찬양해야 하는 지 잘 모른다.
- 그저 내가 할 수 있는 최고의 찬양을 드려야겠다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-07-29', '누가복음', '19장 41~48절', '&nbsp;', '(누가복음 19장)
41. 가까이 오사 성을 보시고 우시며
42. 이르시되 너도 오늘 평화에 관한 일을 알았더라면 좋을 뻔하였거니와 지금 네 눈에 숨겨졌도다
43. 날이 이를지라 네 원수들이 토둔을 쌓고 너를 둘러 사면으로 가두고
44. 또 너와 및 그 가운데 있는 네 자식들을 땅에 메어치며 돌 하나도 돌 위에 남기지 아니하리니 이는 네가 보살핌 받는 날을 알지 못함을 인함이니라 하시니라
45.  성전에 들어가사 장사하는 자들을 내쫓으시며
46. 그들에게 이르시되 기록된 바 내 집은 기도하는 집이 되리라 하였거늘 너희는 강도의 소굴을 만들었도다 하시니라
47. 예수께서 날마다 성전에서 가르치시니 대제사장들과 서기관들과 백성의 지도자들이 그를 죽이려고 꾀하되
48. 백성이 다 그에게 귀를 기울여 들으므로 어찌할 방도를 찾지 못하였더라

