1:감동받는 단어나 구절 찾기(영적터치)

2025년 7월30일 
누가복음 19장41절~48절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
성전/내 집/기도하는 집: 45절 46절 47절
지도자들(대제사장들과 서기관들):47절
알았더라면/알지 못함을:42절 44절

4.주제 만들기: 
기도하는 집

5.하나님 찾기 (관찰)
우시는 예수.
심판을 예견하시는 예수.
성전에서 장사하는 자들을 내쫓으시는 예수.
그틀을 책망하심.
 
6.인간 찾기(관찰)
성전에서 장사하는 사람들.
예수를 죽이려 시도하는 종교 지도자들.

7.하나님 찾기(해석)
예수님이 우셨다. 우주 만물을 창조하신 창조주가 되신 주님께서 우셨다는 것은 정말 큰 사건이라 생각된다. 

아마도 예수님은 믿음 없어 지옥으로 갈 수밖에 없는 수많은 영혼을 생각할 때 슬퍼하신 것 같다.

한편 성전에서 말씀을 가르치실 때 한가롭게 물건을 파는 자들을 내쫓으셨다. 예수님은 외치셨다. 

성전은 ''기도하는 집이다''라고 말씀하셨다. 예수님은 이제 육체의 옷을 입으시고 이 땅에 머물 시간이 얼마 되지 않으셨고 진리에 벗어난 일들에 대하여 책망하셨다. 

성전이 기도 하는 예수님의 집이라 생각할 때 물론 성전과 같지는 않지만 지금 존재하는 교회는 얼마나 영적으로 귀한 장소인지 알게 된다.

8. 인간 찾기(해석)
대제사장들과 서기관 그리고 종교 지도자들은 예수님의 가르침에 감동하고 회개하지 않았다. 

도리어 시기 질투로 가득찬 그들은 예수를 죽이려 했던 것을 보면 그동안 하나님 말씀을 잘못 알고 행동했는데 알 수 있다. 

그들의 마음이 얼마나 단단한지 날마다 성전에서 가르치는 예수의 말씀을 받지 못한다. 

생각해 보면 그들의 이기적이고 교만함이 방패가 되어 생명의 씨앗을 거절하고 있는 듯하다.

9. 적용
교회(믿는자들의 모임)를 더욱 사랑하고 거룩하며 모일때 기도의 시간을 더욱 갖도록 힘써야겠다.
그리고 말씀을 나눌때 진리의 말씀을 잘 저하고 그대로 실천하도록 노력해야겠다.

10. 영적터치 (단어 또는 구절)
46절:내 집은 기도하는 집이 되리라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-07-30', '누가복음', '20장 1~10절', '하늘로부터냐 사람으로부터냐&nbsp;', '누가복음 20장
