7.하나님 찾기(해석)
- 예수님께서는 백성을 가르치시고 복음을 전하는 일을 계속하셨다.
- 자신을 책잡고자 질문하는 대제사장과 서기관과 장로들이 대답할 수 없는 것으로 질문하는 예수님
- 그 질문은 아마도 제사장과 서기관, 그리고 장로들이 예수님을 책잡고자 하고 싶었던 최고의 질문이었을 것이다.
- 포도원 비유를 말씀하시는 예수님

8.인간 찾기(해석)
- 예수님을 책잡아 끌어내려고 예수님께 질문하는 대제사장과 서기관과 장로들
- 그들은 무엇으로 예수님을 책잡을까 머리를 맞대었으나 가장 좋은 질문을 찾지 못했을 것이다.
- 가장 좋은 방법으로 자신들에게 질문하는 예수님의 말씀을 들으며 그들은 당황하며 하는 수 없이 알지 못한다고 대답했다.

9.적용(나) 
- 적대자들은 예수님을 책잡고자 머리를 맞대어 공격한다.
- 신자들 또한 적대자들에게 공격을 당할 수 있다.
- 이 공격을 감당하려면 오직 주님을 의지하여 성령 충만함을 받아, 적대자들의 공격에 대항할 지혜와 능력을 공급받아야 한다.

