- 보내니(11,12,13절)
- 내쫓다(12,15절)
- 포도원 주인(13,15절)
- 돌(17,18절)
- 예수(19,20절)

4. 주제만들기

5. 하나님 찾기 (관찰)
- 포도원을 비유로 말씀하심
- 건축자들이 버린 돌이 모퉁이의 머릿돌이 된다는 것이 무슨 뜻이냐 말씀하신 예수님 

6. 인간 찾기 (관찰)
- 비유의 이야기를 듣고 예수를 잡고자 하지만 백성을 두려워하는 서기관과 대제사장들
- 예수를 총독에 넘기려 정탐을 보내고 그들로 하여금 스스로 의인인척 책잡는 서기관과 대제사장들

7. 하나님 찾기 (해석) 
- 포도원 비유를 통해 한가지 의문점이 생긴다. 
- 종을 세 번이나 보냈음에도 농부들로부터 수확을 실패한 주인은 왜 자신의 아들을 보내며 존대하리라 생각했을까?
- 인간의 논리로 설명되지 않는 비유는 하나님의 입장에서 하나님의 마음으로 해석되어야 한다.
- 포도원 주인은 종들이 쫓김을 당했을 때 당장이라도 농부들을 죽이거나 해코지하러 갈 수 있었다.
- 그러나 자신의 아들을 보내신 목적은 농부들이 해야 할 사명을 깨닫게 하기 위함일 것이다.
- 우리는 하나님으로부터 빚어진 존재이다. 그분을 마땅히 따르고, 그분께 순종하고, 그분을 찬양하는 것이 우리가 해야할 기본적인 일이다. 
- 하나님은 우리에게 자신의 아들인 예수님을 보내셔서 우리를 얼마나 사랑하는지 깨닫게 하시고, 우리가 존재하는 이유를 알게 하시며, 우리를 올바른 길로 인도해주셨다.
- 버림받을 수 있는 존재임에도 우리를 포기하지 않으시는 하나님의 사랑이 느껴진다. 

8. 인간(해석):
- 포도원이라는 작은 공간을 지키려한 농부들, 자신들의 지위와 명예, 세상의 부를 지키려한 서기관과 대제사장들은 매우 어리석다.
- 포도원을 벗어나면 더 큰 공간이 있고, 그 곳에서 누릴 수 있는 것이 많음에도 포도원에 갇혀있다. 
- 나도 포도원에 가둬둔 것들이 있다. 이것을 내려놓고 포도원 밖으로 나아가야 할 것이다. 

9. 적용(나): - 하나님의 사랑만 하루에 한번씩 생각하더라도 내 삶은 달라질 것이다. 그 사랑을 매일 묵상하고 싶다.

10. 영적터치(단어/구절)
- 포도원 주인이 이르되 어찌할까 내 사랑하는 아들을 보내리니 그들이 혹 그는 존대하리라 하였더니

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-08-01', '누가복음', '20장 21~30절', '&nbsp;', '(누가복음 20장)
21. 그들이 물어 이르되 선생님이여 우리가 아노니 당신은 바로 말씀하시고 가르치시며 사람을 외모로 취하지 아니하시고 오직 진리로써 하나님의 도를 가르치시나이다
22. 우리가 가이사에게 세를 바치는 것이 옳으니이까 옳지 않으니이까 하니
23. 예수께서 그 간계를 아시고 이르시되
24. 데나리온 하나를 내게 보이라 누구의 형상과 글이 여기 있느냐 대답하되 가이사의 것이니이다
25. 이르시되 그런즉 가이사의 것은 가이사에게, 하나님의 것은 하나님께 바치라 하시니
26. 그들이 백성 앞에서 그의 말을 능히 책잡지 못하고 그의 대답을 놀랍게 여겨 침묵하니라
27.  부활이 없다고 주장하는 사두개인 중 어떤 이들이 와서
28. 물어 이르되 선생님이여 모세가 우리에게 써 주기를 만일 어떤 사람의 형이 아내를 두고 자식이 없이 죽으면 그 동생이 그 아내를 취하여 형을 위하여 상속자를 세울지니라 하였나이다
29. 그런데 칠 형제가 있었는데 맏이가 아내를 취하였다가 자식이 없이 죽고
30. 그 둘째와 셋째가 그를 취하고

