서기관들과 대제사장들의 간계를 지혜롭게 물리치시는 예수.
 
6.인간 찾기(관찰)
예수를 책잡아 로마 총독에게 넘기려는 서기관들과 대제사장들.
(가이사에게 세금을 내는 것에 대하여 접근함)
부활이 없다고주지ㅣㅇ하는 사두개인.

7.하나님 찾기(해석)

8. 인간 찾기(해석)
서기관들과 대제사장들은 시기 질투와 자신의 권위를 위협하는 예수를 책잡아 로마 총독에게 넘기려 힘썼다. 

그래서 그들은 로마의 최고 권력자인 가이사 황제를 불러들여 세금에 관하여 물었다. 

그들은 유대인으로서 로마의 식민지 안에 있었기에 황제 가이사 이름으로 세금을 회피하는 것은 로마에 대한 도전이라 생각했을 것이다. 

그들은 어쩌면 일반유대인들이 꿈꾸는 로마로부터의 해방을 큰바람일 텐데 더군다나 지도자들이 자신들의 기득권을 유지하기 위하여 가이사에 대한 충성도까지 시험하는 매국노 행위를 서슴지 않고 행한 것이라 여겨진다. 

어쩌면 이러한 모습이 현시대에 살고 있는 사회의 기득권 세력이 모습과 닮았다고 생각된다. 

더 나아서는 대형교회 안에도 이러한 모습들이 매스컴을 통하여 종종 기사화됨을 보면 마음이 많이 씁쓸해진다. 

나 또한 리더로써 섬김보다 권위를 앞세우는 부분이 있는지 점검해야 하겠다.

9. 적용
늘 예수님처럼 영혼을 사랑하고 섬기는데 힘써야겠다. 

스스로 높아지려는 욕망이 있는지 정검해야겠다. 만약 그러한 부분이 보인다면 회개하고 더욱 경각심을 가져야겠다.

