INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-08-04', '누가복음', '21장 1~10절', '나의 보는 눈은 부정확하다', '누가복음 21장
1   예수께서 눈을 들어 부자들이 헌금함에 헌금 넣는 것을 보시고
2   또 어떤 가난한 과부가 두 렙돈 넣는 것을 보시고
3   이르시되 내가 참으로 너희에게 말하노니 이 가난한 과부가 다른 모든 사람보다 많이 넣었도다
4   저들은 그 풍족한 중에서 헌금을 넣었거니와 이 과부는 그 가난한 중에서 자기가 가지고 있는 생활비 전부를 넣었느니라 하시니라
5   어떤 사람들이 성전을 가리켜 그 아름다운 돌과 헌물로 꾸민 것을 말하매 예수께서 이르시되
6   너희 보는 이것들이 날이 이르면 돌 하나도 돌 위에 남지 않고 다 무너뜨려지리라
7   그들이 물어 이르되 선생님이여 그러면 어느 때에 이런 일이 있겠사오며 이런 일이 일어나려 할 때에 무슨 징조가 있사오리이까
8   이르시되 미혹을 받지 않도록 주의하라 많은 사람이 내 이름으로 와서 이르되 내가 그라 하며 때가 가까이 왔다 하겠으나 그들을 따르지 말라
9   난리와 소요의 소문을 들을 때에 두려워하지 말라 이 일이 먼저 있어야 하되 끝은 곧 되지 아니하리라
10   또 이르시되 민족이 민족을, 나라가 나라를 대적하여 일어나겠고

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

1.1분기도
2.본문성경 읽기(3번)
3.반복단어(같은의미 단어)
예수: 1, 5
넣는 것을 보시고: 1, 2
과부: 2, 3, 4
돌: 5, 6(2)
민족: 10(2)
나라: 10(2)

4.주제 만들기: 나의 보는 눈은 부정확하다

5.하나님 찾기(관찰)
- 부자와 가난한 과부의 헌금에 대해 말씀하시는 예수님
- 날이 이르면 성전이 다 무너질 것을 말씀하시는 예수님

6.인간 찾기(관찰)
- 가난한 중에 자신의 생활비 전부를 드린 과부
- 아름다운 돌과 헌물로 꾸민 성전에 대해 말하는 사람들 
- 때와 징조를 묻는 제자들

7.하나님 찾기(해석)
- 헌금의 크기보다 사람의 마음이 중요함을 말씀하시는 예수님
- 헌금을 내는 개인은 하나님 앞에서 하나님을 사랑함으로 예물을 드려야 한다.
- 다른 사람이 헌금 내는 것을 볼 때 헌금의 크기를 보고 사람을 판단하면 안 된다.
- 헌금은 자신의 생활 형편을 보고 미리 마음으로 정하여 즐겨내야 한다.

- 성전이 보기에 화려하지만, 완전히 무너질 날이 올 것이다.
- 이 날이 오되, 신자들은 미혹되지 않도록 주의해야 한다.
- 많은 사람이 자신이 예수라고 하면서 속이며, 때가 가까이 왔다고 속일 것이다.
- 난리와 소요의 소문이 있을 것이지만, 그때가 끝은 되지 않을 것이다. 

8.인간 찾기(해석)
- 어쩌면 헌금을 많이 한 부자는 자신의 헌금을 정성껏 드렸을 수도 있지만, 그 크기를 자랑스러워하며 보는 사람들에게 자신의 재력을 과시하고 우쭐했을 가능성이 있다. 
- 가난한 과부가 생활비의 전부를 드렸다는 것은, 자신이 먹을 끼니를 줄인 것일 수 있고, 자녀가 고기 반찬 먹고 싶다고 하는 것을 눈물로 참고 하나님께 드린 것일 수 있다.

- 성전의 화려함을 보고 감탄하는 사람들
- 우리는 지금의 화려함을 볼 수는 있으나 나중 일을 알 수 없다.

- 환란의 때가 오는데 우리를 속이는 자가 먼저 온다.
- 신자들은 속지 말아야 한다.
- 난리와 소요의 소문이 있으나, 그런 일이 일어나더라도 환란의 때는 아니다.

9.적용(나) 
- 어머니께서는 생전에 가난한 개척교회 사모였다.
- 우리 생활비도 부족한데, 예배가 끝나면 조용히 가난한 집사님께 가서 만원짜리 한 장을 쥐어주며 보내시곤 하셨다. 내가 볼 때 그 집사님 보다 우리가 더 가난했는데...
- 나는 반찬 투정을 자주 했다. 고기가 먹고 싶을 때는 참치 통조림을 한 통 사서 먹었다. 
- 어머니께서는 엄마 고기 반찬이 너무 맛있어요 엄마 최고에요 라는 아들의 말을 듣는 것 대신 그들을 섬기는 것을 택하셨다.
- 아마도 가난한 중에 생활비로 헌금을 내는 집사님을 사랑하셨기 때문일 것이다.

- 사람의 외모보다 예수님을 사랑하는 순수한 마음을 볼 줄 아는 그런 사람이 되고 싶다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-08-05', '누가복음', '21장 21~30절', '예루살렘의 멸망과 예수님의 재림', '목요일 묵상
누가복음 21장
21   그 때에 유대에 있는 자들은 산으로 도망갈 것이며 성내에 있는 자들은 나갈 것이며 촌에 있는 자들은 그리로 들어가지 말지어다
22   이 날들은 기록된 모든 것을 이루는 징벌의 날이니라
23   그 날에는 아이 밴 자들과 젖먹이는 자들에게 화가 있으리니 이는 땅에 큰 환난과 이 백성에게 진노가 있겠음이로다
24   그들이 칼날에 죽임을 당하며 모든 이방에 사로잡혀 가겠고 예루살렘은 이방인의 때가 차기까지 이방인들에게 밟히리라
25   일월 성신에는 징조가 있겠고 땅에서는 민족들이 바다와 파도의 성난 소리로 인하여 혼란한 중에 곤고하리라
26   사람들이 세상에 임할 일을 생각하고 무서워하므로 기절하리니 이는 하늘의 권능들이 흔들리겠음이라
27   그 때에 사람들이 인자가 구름을 타고 능력과 큰 영광으로 오는 것을 보리라
28   이런 일이 되기를 시작하거든 일어나 머리를 들라 너희 속량이 가까웠느니라 하시더라
29   이에 비유로 이르시되 무화과나무와 모든 나무를 보라
30   싹이 나면 너희가 보고 여름이 가까운 줄을 자연히 아나니

