4.주제 만들기: 예루살렘의 멸망과 예수님의 재림

5.하나님 찾기(관찰)
- 예루살렘의 멸망과 재림에 대해 말씀하시는 예수님

6.인간 찾기(관찰)

7.하나님 찾기(해석)
- 예루살렘에 환난이 있을 것인데, 이날은 기록된 모든 것을 이루는 징벌의 날이다.
- 로마 군인에 의해 예수살렘은 멸망될 것이고, 많은 사람들이 죽게 될 것을 예언하신 것.

- 예루살렘은 이방인의 때가 될 때까지 이방인에게 밟힐 것이다.
- 예루살렘은 멸망할 것이나, 이방인의 때가 될 때까지이다.
- 로마는 예루살렘을 짓밟고 그리스도인을 죽이거나 가뒀으나, 훗날 기독교를 국교로 공인하게 되는 놀라운 역사적 사실이 있다. 그리고 이 로마를 통해 기독교가 세계로 퍼졌다.

- 예루살렘의 멸망은 그리스도인들에게 너무나 괴로운 일이지만 잠시일 뿐이다. 
- 기한이 있다.
- 곧 소망의 날이 온다는 것이고, 실제로 말씀대로 이루어졌다.

- 예수님이 재림하시기 전에는 해와 달과 별들이 변화될 것이며,
- 바다가 요동하고 하늘의 권능들이 흔들릴 것이다.
- 이것은 몇몇 사람들만 아는 현상이 아니라, 사람이라면 누구나 알 수 있는 그런 현상이다.

8.인간 찾기(해석)
- 신자에게 곤고한 날이 찾아온다. 
- 어쩌면 자주, 많이 찾아올 수 있다.
- 그러나 우리 신자에게 이것은 기한이 있는 날일 뿐이다.
- 우리 주 예수 그리스도께서는 곤고한 날 다음 소망의 날을 반드시 주신다. 

- 자기가 예수라고 주장하는 자들에게 속지 말아야 한다.
- 마지막 날은 예수님의 말씀처럼 사람 모두가 알 수 있는 모습으로 온다.
- 26절.. 무서워하므로 기절하리니

9.적용(나) 
- 인생의 곤고한 날 우리에게 소망을 주시는 예수님을 바라보며 살아가야겠다.
- 마지막 날에 어떤 징조가 있을지 말씀해 주셔서 너무나 다행이고 감사하다.
- 나는 그날까지 내게 주어진 일을 하면 된다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-08-06', '누가복음', '21장 11~20절', '&nbsp;', '(누가복음 21장)
11. 곳곳에 큰 지진과 기근과 전염병이 있겠고 또 무서운 일과 하늘로부터 큰 징조들이 있으리라
12. 이 모든 일 전에 내 이름으로 말미암아 너희에게 손을 대어 박해하며 회당과 옥에 넘겨 주며 임금들과 집권자들 앞에 끌어 가려니와
13. 이 일이 도리어 너희에게 증거가 되리라
14. 그러므로 너희는 변명할 것을 미리 궁리하지 않도록 명심하라
15. 내가 너희의 모든 대적이 능히 대항하거나 변박할 수 없는 구변과 지혜를 너희에게 주리라
16. 심지어 부모와 형제와 친척과 벗이 너희를 넘겨 주어 너희 중의 몇을 죽이게 하겠고
17. 또 너희가 내 이름으로 말미암아 모든 사람에게 미움을 받을 것이나
18. 너희 머리털 하나도 상하지 아니하리라
19. 너희의 인내로 너희 영혼을 얻으리라
20.  너희가 예루살렘이 군대들에게 에워싸이는 것을 보거든 그 멸망이 가까운 줄을 알라

