2025년 8월06일 
누가복음 21장11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
징조/증거: 11절 13절 
손을 대어/끌어/죽이게 하겠고/미움을 받을 것: 12절 16절 17절
상하지 아니함/영혼을 얻음:18절 19절
내 이름: 12절 17절

4.주제 만들기: 
마지막때 징조

5.하나님 찾기 (관찰)
환난때 자녀들을 지키시는 주님.
상황에 따라 지혜를 주심
 
6.인간 찾기(관찰)
인내로 환난때 영혼을 얻는 주님의 자녀들.
환난때 부모나 형제와 친척과 벗 조차도 집권자들에게 넘김.

7.하나님 찾기(해석)

8. 인간 찾기(해석)
예수님은 마지막 때 일어날 여러 가지 재앙이나 징조를 미리 알려주셨다. 

그리고 그때는 예수님의 이름을 지키고자 하는 자들에게는 큰 핍박과 어려움을 겪는다고 하셨다. 

그중 큰 고통 중 하나는 가까운 혈육인 부모와 형제 친척들이 압제자들에게 넘겨준다는 것이다. 

그중에 죽임을 당하는 자들도 있다는 내용이다. 그런데도 나머지 자녀들은 주님께서 머리털 하나라도 건들지 못하게 상황에 따라 지혜롭게 대처할 수 있는 언변도 주신다는 것이다. 

결국 마지막 때에는 주님의 이름으로 고난도 있지만 주님의 이름으로 영생을 받을 수 있는 특권이 있다는 것을 생각하면 작은 고난 뒤에 있을 큰 축복이 있다는 것이다. 

그러므로 평상시 늘 깨어 기도하고 주님의 말씀을 묵상하며 산다는 것이 얼마나 중요하고 귀한 일인지 더욱 깨우치게 된다.

9. 적용
평상시 인내하는 훈런을 잘받아서 혹시 환난때 라도 믿음을 지키는 주님의 자녀가 되야겠다.

10. 영적터치 (단어 또는 구절)
18절:너희 머리털 하나도 상하지 아니하리라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-08-07', '누가복음', '21장 31~38절', '항상 기도하고 깨어있어야하는 이유', '[눅21:31-38]
31 이와 같이 너희가 이런 일이 일어나는 것을 보거든 하나님의 나라가 가까이 온 줄을 알라
32 내가 진실로 너희에게 말하노니 이 세대가 지나가기 전에 모든 일이 다 이루어지리라
33 천지는 없어지겠으나 내 말은 없어지지 아니하리라
34 너희는 스스로 조심하라 그렇지 않으면 방탕함과 술취함과 생활의 염려로 마음이 둔하여지고 뜻밖에 그 날이 덫과 같이 너희에게 임하리라
35 이 날은 온 지구상에 거하는 모든 사람에게 임하리라
36 이러므로 너희는 장차 올 이 모든 일을 능히 피하고 인자 앞에 서도록 항상 기도하며 깨어 있으라 하시니라
37 예수께서 낮에는 성전에서 가르치시고 밤에는 나가 감람원이라 하는 산에서 쉬시니
38 모든 백성이 그 말씀을 들으려고 이른 아침에 성전에 나아가더라

