7. 하나님 찾기 (해석) 
- 예수님께선 환난이 올 그날에 대해 미리 말씀해주셨다. 
- 그 날은 실제 예수님이 이 땅에 다시 오실 그날일 수도 있고, 
- 예수님의 십자가 사건 이후 복음이 온 세계로 뻗어나갈 것을 아시고, 복음으로 인해 핍박 받을 제자들과 우리를 위해 남겨주신 말씀이기도 하다. 
