1:감동받는 단어나 구절 찾기(영적터치)

2025년 8월09일 
누가복음 22장1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
유월절: 1절 7절 8절
무교절: 1절 7절
대제사장들: 2절 4절 
죽일까 궁리하니/넘겨 줄 방도를 의논하매/넘겨 줄 기회를 찾더라: 2절 4절 6절
유월을 준비: 8절 9절 

4.주제 만들기: 
유월절을 준비하는 예수.

5.하나님 찾기 (관찰)
제자들과 더불어 유월을 준비하는 예수.
 
6.인간 찾기(관찰)
대제사장들과 서기관들이 백성을 두려워하여 예수를 죽이려 모의를 함.
가롯유다가 예수를 배신함.

7.하나님 찾기(해석)
7절에 보면 "유월절 양을 잡을 무교절 날이 이른지라" 기록되어 있다. 

유대인들에게는 큰 종교적 행사이지만 예수님 입장에서는 스스로 목숨을 잃으시는 때가 다가옴을 암시하는 것이다. 

인간적인 예수님의 처지에서 생각하면 가슴이 먹먹해진다. 하나님 말씀을 가르치는 대제상들과 서기관들이 하나님의 아들을 알아보지 못하고 죽이려 의논하고 있다. 

그럴 뿐만 아니라 3년 동안 동고동락했던 제자 유다가 자신의 스승을 배신하고 언약까지 하였다. 예수님은 얼마나 외롭고 슬프셨을까? 

이러한 모든 고통의 시간을 감내하시고 도살장에 끌려가는 어린양처럼 조용히 유월절을 제자들과 맞이하고 계신다. 

예수님의 너무나 크신 사랑을 생각할 때 어떠한 환경에서도 감사하지 못할 일이 있겠는가 생각해 본다.

8. 인간 찾기(해석)

9. 적용
요즘 목감기가 와서 육체적으로 조금 힘들다. 그럴 뿐만아니라 갑자기 이사를 가게되었는데 폭염 가운데 물건을 정리하고 새로운 집을 찾는 모든 과정이 정신적으로도 피로가 몰린다. 그러한 분주한 가운데에서도 3331큐티를 통하여 예수님의 크신 사랑하는 발견할때 모든 피로가 회복됨을 느낀다. 오늘도 감사함으로 웃고 살아야겠다.

10. 영적터치 (단어 또는 구절)
7절: 유월절 양을 잡을 무교절날이 이른지라 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-08-09', '누가복음', '22장 11~20절', '&nbsp;', '(누가복음 22장)
11. 그 집 주인에게 이르되 선생님이 네게 하는 말씀이 내가 내 제자들과 함께 유월절을 먹을 객실이 어디 있느냐 하시더라 하라
12. 그리하면 그가 자리를 마련한 큰 다락방을 보이리니 거기서 준비하라 하시니
13. 그들이 나가 그 하신 말씀대로 만나 유월절을 준비하니라
14.  때가 이르매 예수께서 사도들과 함께 앉으사
15. 이르시되 내가 고난을 받기 전에 너희와 함께 이 유월절 먹기를 원하고 원하였노라
16. 내가 너희에게 이르노니 이 유월절이 하나님의 나라에서 이루기까지 다시 먹지 아니하리라 하시고
17. 이에 잔을 받으사 감사 기도 하시고 이르시되 이것을 갖다가 너희끼리 나누라
18. 내가 너희에게 이르노니 내가 이제부터 하나님의 나라가 임할 때까지 포도나무에서 난 것을 다시 마시지 아니하리라 하시고
19. 또 떡을 가져 감사 기도 하시고 떼어 그들에게 주시며 이르시되 이것은 너희를 위하여 주는 내 몸이라 너희가 이를 행하여 나를 기념하라 하시고
20. 저녁 먹은 후에 잔도 그와 같이 하여 이르시되 이 잔은 내 피로 세우는 새 언약이니 곧 너희를 위하여 붓는 것이라

