2025년 8월10일 
누가복음 22장11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
유월절: 11절 16절 
감사 기도: 17절 19절
떡/ 몸: 19절
원하고/원하였노라: 15절
잔: 17절 20절

4.주제 만들기: 
마지막 만찬

5.하나님 찾기 (관찰)
마지막 만찬을 제자들과 함께하시는 예수.
최초의 성찬식을 가르치시는 예수.
하나님께 감사 기도 드리는 예수.
 
6.인간 찾기(관찰)
예수님과 함께 성 만찬에 참석한 사도들.

7.하나님 찾기(해석)
예수님은 십자가를 지실 날이 얼마 남지 않은 시점에서 제자들과 더불어 마지막 만찬을 가지셨다. 

그리고 제자들에게 성만찬을 최초로 행하셨다. 성만찬은 포도주를 마시고 떡을 먹는 것은 구원과 직접적이지는 않지만, 주님의 희생을 기념하고 믿는 자들의 화목을 도모하는 중요한 의식이다. 

특별히 신자들은 각자의 구원을 주신 예수님께 늘 감사하는 마음을 갖고 살아야겠다. 

그런데도 17절에 보면 "이에 잔을 받으사 감사 기도 하시고" 기록된 것을 보면 감사를 할 대상이 바뀐 것을 느낀다. 

수혜자인 신자가 감사해야 하는데 희생자인 예수가 하나님께 감사하고 계신다. 이것을 보면 세상 가운데 사는 신자를 포함한 수많은 사람은 자신에게 피해를 주는 대상자들에게 굉장한 불쾌감을 느끼며 심지어 관계를 단절하는 것이 보편적인 상황이다. 

그런데 예수님은 자신이 모든 죄를 대신 짊어지시고 감사를 하는 것은 이성적으로 이해하기 힘든 큰 사랑의 영역이다. 

그런데도 주님은 성만찬을 기념하시며 자녀들에게 그렇게 살 것을 말씀하신다. 

인간의 힘으로 할 수 없지만 주님이 함께하시면 할 수 있을 줄 믿습니다!!
늘 감사하며 살게 하옵소서!!

8. 인간 찾기(해석)

9. 적용
오늘 더욱 주님의 십자가 사랑을 묵상해야겠다.
오늘 더욱 감사하는 하루가 되도록 노력해야겠다.

