INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-08-10', '누가복음', '22장 21~30절', '이 세상의 사랑과 다른 하나님의 사랑', '[눅22:21-30]
21 그러나 보라 나를 파는 자의 손이 나와 함께 상 위에 있도다
22 인자는 이미 작정된 대로 가거니와 그를 파는 그 사람에게는 화가 있으리로다 하시니
23 그들이 서로 묻되 우리 중에서 이 일을 행할 자가 누구일까 하더라
24 또 그들 사이에 그 중 누가 크냐 하는 다툼이 난지라
25 예수께서 이르시되 이방인의 임금들은 그들을 주관하며 그 집권자들은 은인이라 칭함을 받으나
26 너희는 그렇지 않을지니 너희 중에 큰 자는 젊은 자와 같고 다스리는 자는 섬기는 자와 같을지니라
27 앉아서 먹는 자가 크냐 섬기는 자가 크냐 앉아서 먹는 자가 아니냐 그러나 나는 섬기는 자로 너희 중에 있노라
28 너희는 나의 모든 시험 중에 항상 나와 함께 한 자들인즉
29 내 아버지께서 나라를 내게 맡기신 것 같이 나도 너희에게 맡겨
30 너희로 내 나라에 있어 내 상에서 먹고 마시며 또는 보좌에 앉아 이스라엘 열두 지파를 다스리게 하려 하노라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

1. 1분기도

2. 본문성경 읽기(3번)

3. 반복단어 찾기(형광펜 추천)
- 먹는자(27절)
- 섬기는자(27절)
- 맡기다(29절)

4. 주제만들기: 이 세상의 사랑과 다른 하나님의 사랑

5. 하나님 찾기 (관찰)
- 최후의 만찬에서 자신을 배반할 사람이 있음을 알려주신 예수님
- 제자들의 다툼을 보고 큰 자는 젊은 자와 같고 다스리는 자는 섬기는 자가 되어야 한다고 말씀하신 예수님
- 예수님은 섬기는 자로 모든 시험에 함께한 제자들에게 하나님께서 자신에게 이 나라를 맡기신 것처럼 제자들에게 이 나라를 맡기신다고 말씀하신 예수님
- 내 나라에 있고, 내 상에서 먹고 마시며, 보좌에 앉아 열두 제자를 다스릴 것이라 말씀하신 예수님 

6. 인간 찾기 (관찰)
- 최후의 만찬에서 배신 할 자를 찾는 제자들
- 제자들 중 누가 더 높은 자인지 다툼을 하는 제자들

7. 하나님 찾기 (해석) 
- 이보다 완벽한 사랑이 있을까? 최후의 만찬을 통해 마지막까지도 자신의 사랑을 인간에게 보여주셨다. 
- 예수님은 십자가를 지시기 전 감사 기도를 드리셨고, 섬기는 자로 오셨음을 다시 한번 언급하셨다.
- 인간의 시선으로 도무지 이해가 안 되는 선택을 하신 것이다. 
- 더불어 자신 앞에 배신자가 있음에도 그 또한 하나님의 뜻임을 인정하고 다투는 제자들에게 높은 자가 아닌 낮은 자로, 섬김을 받는 자가 아닌 섬기는 자로의 소명을 주셨다.
- 이것은 이 시대를 살아가는 우리도 지켜야할 사명일 것이다. 

8. 인간(해석):
- 예수님께서 잡혀간다는 것을 그저 심문 수준으로 끝날 것이라 생각했을까? 
- 제자들의 철 없는 행동에 어이가 없다. 
- 세상은 그렇다. 서열이 있고, 남보다 높아지려는 마음, 섬기는 것보다 섬김을 받는 것이 마땅하다고 생각한다.
- 그러나 하나님이 만드신 세상은 그런 곳이 아니다.
- 예수님께선 네 이웃을 사랑하라고 하셨다. 사랑이 있어야 섬김이 이루어지는데 
- 사랑은 개인이 가진 성품이 아니라 예수님의 사랑을 경험하고 느낀자 만이 온전히 그 사랑을 실천할 수 있다.

9. 적용(나): 
- 이해할 수 없는 사랑을 주시는 하나님께 감사하다. 이 세상과 완전히 다른, 차원이 다른 사랑에 감사하다.
- 낮은 자, 섬기는 자로 평생 살다 천국에 가고 싶다.

10. 영적터치(단어/구절)
- 너희는 그렇지 않을지니 너희 중에 큰 자는 젊은 자와 같고 다스리는 자는 섬기는 자와 같을지니라

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

