4.주제 만들기: 
예수님의 고뇌

5.하나님 찾기 (관찰)
간절히 기도하시는 예수.
잠자는 제자들을 깨우시는 예수.
배신자 가롯유다와 말씀하시는 예수.
 
6.인간 찾기(관찰)
잠자고 있는 제자들.
예수님을 잡기위하여 다가오는 가롯유다와 무리.

7.하나님 찾기(해석)
예수님 측면에서 보면 너무 힘든 상황임이 쉽게 짐작이 된다. 먼저는 삼위일체인 하나님 아버지와 일시적이라도 떨어질 수밖에 없는 환경이 되었다. 

그러한 부분이 너무 괴로워서 예수님은 "이 잔을 내게서 옮기소서" 하셨을 것이다. 그런데도 결국 적으로는 "그러나 내 원대로 마시옵고 아버지 원대로 되기를 원하나이다"라고 말씀하심으로 하나님 뜻에 순종하는 것을 알 수 있다. 

두 번째는 죽음을 앞두고 땀방울이 핏방울 되기까지 기도하시는데 자는 제자들의 약한 모습이다. 답답해 보이셨을 것이다. 

아마 이러한 모습은 나의 모습이 아닐까 반성해 본다. 나도 때때로 몸이 피곤하다는 핑계로 기도 자리를 게을리하는 경우를 본다. 

그러한 가운데 제자 가롯 유다는 스승인 예수를 잡으려고 사람들과 왔다. 인간적인 측면에서 보면 예수님은 너무 괴로울 수밖에 없는 모습이다. 사랑하는 아버지께 버림받고 제자에게도 배신당하는 정말 외로운 상태인 것 같다. 

단지 예수님은 영혼을 구원하시고자 자신을 철저히 버리셨다.
마음이 먹먹해진다. 

누가, 이 크신 사랑을 감당할 수 있을까? 오늘도 십자가 사랑에 감사밖에 할 수 있는 일이 없다.

8. 인간 찾기(해석)

9. 적용
오늘도 십자가 사랑을 더욱 묵상하는 하루를 보내야겠다.
또한 육체가 피곤해도 기도의 끈을 놓지 않아야겠다.

